L2_1 = {}
L2_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@2#Talk"
L2_1.m_CutScenProcessKey = 2
L2_1.m_CutScenID = 5100201
L2_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Talk_KOREA = "신은 인간을 사랑했다."
L2_1.m_fTalkTime = 0.03
L2_1.m_bTalkCenterFadeIn = true
L2_1.m_Talk_JPN = "神は人間を愛した。"
L2_1.m_Talk_ENG = "God loved humans."
L2_1.m_Talk_TWN = "神曾經愛過人類。"
L2_1.m_Talk_THA = "เทพเจ้านั้นรักมนุษย์"
L2_1.m_Talk_VTN = "Thần đã từng yêu quý nhân loại."
L2_1.m_Talk_SCN = "神爱上了人类。"
L2_1.m_Talk_DEU = "Gott liebte die Menschen."
L2_1.m_Talk_FRA = "Jadis vivait un dieu qui aimait éperdument les humains."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 5100201
L3_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Talk_KOREA = "그렇게 신과 인간 사이에 자손이 태어났다."
L3_1.m_fTalkTime = 0.03
L3_1.m_bTalkCenterFadeIn = true
L3_1.m_Talk_JPN = "そうして神と人間の間に子が生まれた。"
L3_1.m_Talk_ENG = "And thus, a newborn child emerged between God and a human."
L3_1.m_Talk_TWN = "就這樣，神與人之間生出後裔。"
L3_1.m_Talk_THA = "เช่นนั้นเอง ธิดาของเทพเจ้าและมนุษย์จึงถือกำเนิดขึ้น"
L3_1.m_Talk_VTN = "Vì thế, một đứa trẻ sơ sinh đã xuất hiện, lai giữa Thần và Người."
L3_1.m_Talk_SCN = "就这样，神和人之间孕育了后代。"
L3_1.m_Talk_DEU = "Und so erblickte der Nachkomme zwischen Gott und einem Menschen das Licht der Welt."
L3_1.m_Talk_FRA = "De cet amour naquit une petite fille."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 5100201
L4_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Talk_KOREA = "신은 그의 자손에게 많은 걸 베풀고 싶었다."
L4_1.m_fTalkTime = 0.03
L4_1.m_bTalkCenterFadeIn = true
L4_1.m_Talk_JPN = "神は自らの子孫に与えられる限りの恩恵を与えたかった。"
L4_1.m_Talk_ENG = "God wanted to give her child everything."
L4_1.m_Talk_TWN = "神想把一切都給他的後裔。"
L4_1.m_Talk_THA = "เทพเจ้าปรารถนาจะมอบทุกสิ่งให้ธิดาของนาง"
L4_1.m_Talk_VTN = "Thần đã muốn trao cho đứa trẻ mọi thứ."
L4_1.m_Talk_SCN = "神想把一切都给她的后裔。"
L4_1.m_Talk_DEU = "Gott wollte ihrem Kind alles geben."
L4_1.m_Talk_FRA = "Fou de joie, le dieu voulut tout donner à son enfant."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 5100201
L5_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Talk_KOREA = "그래서 인간들이 자신을 섬기는 것처럼……"
L5_1.m_fTalkTime = 0.03
L5_1.m_bTalkCenterFadeIn = true
L5_1.m_Talk_JPN = "それで人間が神に仕えるのと同じように……"
L5_1.m_Talk_ENG = "Just as humans worshiped her..."
L5_1.m_Talk_TWN = "於是像人類侍奉自己一樣……"
L5_1.m_Talk_THA = "ดังเช่นที่มนุษย์บูชานาง..."
L5_1.m_Talk_VTN = "Cũng như nhân loại đã thờ phụng ngài..."
L5_1.m_Talk_SCN = "所以为了人类能像侍奉自己那样……"
L5_1.m_Talk_DEU = "So wie die Menschen sie verehrten ..."
L5_1.m_Talk_FRA = "C'est ainsi qu'il la dota d'une partie de ses pouvoirs, et en fit une prêtresse."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 5100201
L6_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Talk_KOREA = "아이에게 권능을 주고, 무녀로 섬겼다."
L6_1.m_fTalkTime = 0.03
L6_1.m_bTalkCenterFadeIn = true
L6_1.m_Talk_JPN = "子に権能を与え、巫女として仕えさせた。"
L6_1.m_Talk_ENG = "She empowered her child, and appointed her child as a priestess."
L6_1.m_Talk_TWN = "給予後裔權能做巫女侍奉神。"
L6_1.m_Talk_THA = "นางมอบพลังอำนาจแก่ธิดาตน และแต่งตั้งนางเป็นนักบวชหญิง"
L6_1.m_Talk_VTN = "Thần đã trao quyền cho đứa trẻ, chỉ định nó là nữ tu sĩ của mình..."
L6_1.m_Talk_SCN = "她给予后裔权能，并让她作为巫女侍奉神。"
L6_1.m_Talk_DEU = "Verlieh sie ihrem Kind Macht und ernannte es zur Priesterin."
L6_1.m_Talk_FRA = "Pour que les humains la vénèrent, tout comme ils le vénéraient lui."
