L9_1 = {}
L9_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 5100201
L9_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "GOD_NPC_NANAHARA2_NULL"
L9_1.m_Talk_KOREA = "이걸로, 여덟 머리 중 일곱을 베었도다."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "これで、八つの頭のうち七つを切り取った。"
L9_1.m_Talk_ENG = "Seven severed. Only one left, thou."
L9_1.m_Talk_TWN = "已經斬掉八顆中的七顆，"
L9_1.m_Talk_THA = "สะบั้นสิ้นแล้วเจ็ด เหลือเพียงหนึ่ง"
L9_1.m_Talk_VTN = "Bảy cái đầu đã bị chặt đứt. Chỉ còn một cái cuối cùng."
L9_1.m_Talk_SCN = "如今，八颗脑袋已经砍掉了七颗。"
L9_1.m_Talk_DEU = "Damit habe ich sieben deiner acht Köpfe abgetrennt."
L9_1.m_Talk_FRA = "Et de sept. Il ne te reste plus qu'une tête, maintenant."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 5100201
L10_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "GOD_NPC_NANAHARA2_NULL"
L10_1.m_Talk_KOREA = "하지만 너의 독기는 여전히 이승을 허물고 있으니…… 이대로는 세상이 무너지고 말리라."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "だが、お主の毒気はいまだ現世を侵し続けている……このままでは世界は崩壊してしまうであろう。"
L10_1.m_Talk_ENG = "Yet, thy venom still lingers in this world... collapsed shall it be if left unchecked."
L10_1.m_Talk_TWN = "但你的毒氣依舊在摧毀現世……再這樣下去，世界會毀滅的。"
L10_1.m_Talk_THA = "กระนั้น พิษยังคงหลงเหลืออยู่ในโลกนี้... หากมิอาจควบคุมได้คงล่มสลายเป็นแน่"
L10_1.m_Talk_VTN = "Tuy nhiên, nọc độc của mi vẫn rải rác trong thế giới này...và thế giới sẽ đổ nát nếu không được kiểm soát."
L10_1.m_Talk_SCN = "但你的毒气还在摧毁现世……照这样下去，世界终将分崩离析。"
L10_1.m_Talk_DEU = "Aber dein Gift zerstört immer noch diese Welt ... Wenn das so weitergeht, dann ist die Welt dem Untergang geweiht."
L10_1.m_Talk_FRA = "Pourtant ton venin, lui, continue de se répandre... si je ne fais rien, ce monde finira par s'écrouler."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 5100201
L11_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "GOD_NPC_NANAHARA2_NULL"
L11_1.m_Talk_KOREA = "그러니, 네 마지막 머리를 베어야겠구나. 역신 오로치여."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "それゆえ、お主の最後の頭を切り取らねばならぬ。疫病神オロチよ。"
L11_1.m_Talk_ENG = "Thus, I shall sever thy last head as well, Orochi the Plague God."
L11_1.m_Talk_TWN = "因此，必須斬掉你最後一顆頭，瘟神大蛇。"
L11_1.m_Talk_THA = "เช่นนั้นแล้ว ข้าจักกุดหัวสุดท้ายนั่นทิ้งเสียด้วย เทพภัยพิบัติโอโรจิเอ๋ย"
L11_1.m_Talk_VTN = "Vì vậy, ta sẽ chặt đứt cả cái đầu cuối cùng của mi, Thần Bệnh Dịch Orochi à."
L11_1.m_Talk_SCN = "所以，我要砍掉你最后一个脑袋，瘟神大蛇。"
L11_1.m_Talk_DEU = "Deshalb muss ich auch noch deinen letzten Kopf abtrennen, Orochi, Gott der Verwesung."
L11_1.m_Talk_FRA = "Orochi, le Dieu du Fléau. L'heure est venue de trancher la dernière de tes têtes."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 5100201
L12_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_HATE"
L12_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "이 몸은 죽지 않는다. 망자를 다스리는 네놈이라면 잘 알고 있을 텐데?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "我は死なん。亡者を治める貴様ならよく知っているはずだ。"
L12_1.m_Talk_ENG = "I am immortal. You, the ruler of death, should know this, no?"
L12_1.m_Talk_TWN = "這副軀體是不會死的，管理死人的你應該很清楚吧？"
L12_1.m_Talk_THA = "ตัวข้านั้นเป็นอมตะ ผู้ปกครองความตายย่อมควรรู้เรื่องนั้นดีมิใช่หรือ?"
L12_1.m_Talk_VTN = "Ta là bất tử. Một kẻ thống trị cái chết hẳn phải biết điều này, đúng chứ?"
L12_1.m_Talk_SCN = "我不会死。掌管亡者的你应该很清楚才对吧？"
L12_1.m_Talk_DEU = "Ich bin unsterblich. Du, der Herrscher des Todes, solltest das nur zu gut wissen, nicht wahr?"
L12_1.m_Talk_FRA = "À quoi bon ? Je suis immortel. Tu devrais le savoir, non ? Toi, le souverain des morts."
