L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 5100201
L14_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "GOD_NPC_NANAHARA2_NULL"
L14_1.m_Talk_KOREA = "네 머리들을 베어 봉한다면, 다시 쉽게 인간들을 해칠 순 없겠지."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "頭を切り封印すれば、人間を容易く害することはできなくなる。"
L14_1.m_Talk_ENG = "With thy heads sealed, thou shalt not easily cast doom on man."
L14_1.m_Talk_TWN = "等我把你的頭斬下，再將你封印起來，你便無法再危害人類。"
L14_1.m_Talk_THA = "เพียงผนึกหัวทั้งปวงไว้ เจ้าย่อมมิอาจบันดาลหายนะแก่มนุษย์ได้โดยง่าย"
L14_1.m_Talk_VTN = "Khi những cái đầu này bị phong ấn, chúng không thể reo giắc tai họa cho con người nữa."
L14_1.m_Talk_SCN = "砍掉你的脑袋封印起来，你就不能再轻易害人了吧。"
L14_1.m_Talk_DEU = "Wenn ich deine abgetrennten Köpfe versiegele, wirst du den Menschen nicht mehr so ​​leicht Schaden zufügen können."
L14_1.m_Talk_FRA = "À défaut de te tuer, je scellerai tes têtes pour te neutraliser. Et ainsi, tu ne nuiras plus jamais aux humains."
