L18_1.m_Talk_KOREA = "하지만 그것들은……"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "しかし、あやつらは……"
L18_1.m_Talk_ENG = "But those vile creatures..."
L18_1.m_Talk_TWN = "他們卻……"
L18_1.m_Talk_THA = "แต่พวกสิ่งมีชิวิตสามานย์นั่น..."
L18_1.m_Talk_VTN = "Nhưng những sinh vật thấp hèn đó ..."
L18_1.m_Talk_SCN = "但是他们……"
L18_1.m_Talk_DEU = "Aber diese abscheulichen Kreaturen ..."
L18_1.m_Talk_FRA = "Mais ces viles créatures..."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 5100201
L19_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "내가…… 가장 소중히 여기는 분을 죽였어."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "我が……もっとも大切にしていた人間を殺した。"
L19_1.m_Talk_ENG = "They... They slaughtered my beloved."
L19_1.m_Talk_TWN = "殺死……我的摯愛。"
L19_1.m_Talk_THA = "พวกมัน... พวกมันสังหารดวงใจข้า"
L19_1.m_Talk_VTN = "Chúng...Chúng sát hại người ta thương yêu."
L19_1.m_Talk_SCN = "杀死了……我最重要的人。"
L19_1.m_Talk_DEU = "Sie ... haben die Person getötet, die mir am meisten am Herzen lag."
L19_1.m_Talk_FRA = "Ils... ils ont massacré ma fille, la prunelle de mes yeux."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 5100201
L20_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L20_1.m_Pos = "C"
L20_1.m_Crash = 20
L20_1.m_Talk_KOREA = "그 힘을 빼앗아, 영생을 얻겠다는 이유만으로!"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "その力を奪い、永生を得たいという理由だけで！"
L20_1.m_Talk_ENG = "All because they wanted to take her powers and gain eternal life!"
L20_1.m_Talk_TWN = "只因為他們相信，奪取她的力量可以得到永生！"
L20_1.m_Talk_THA = "เพียงเพราะอยากช่วงชิงพลังของนางและมีชีวิตอมตะ!"
L20_1.m_Talk_VTN = "Tất cả chỉ vì muốn tước đoạt sức mạnh của cô ấy và giành lấy sự bất tử!"
L20_1.m_Talk_SCN = "只是因为想要夺走那股力量获得永生！"
L20_1.m_Talk_DEU = "Nur, weil sie ihre Kräfte stehlen und ewiges Leben erlangen wollten!"
L20_1.m_Talk_FRA = "Tout cela parce qu'ils voulaient s'emparer de ses pouvoirs et gagner la vie éternelle !"
