L22_1.m_Talk_KOREA = "알고 있다네."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "わかっている。"
L22_1.m_Talk_ENG = "So I am aware."
L22_1.m_Talk_TWN = "我知道。"
L22_1.m_Talk_THA = "ข้าเองก็ทราบดี"
L22_1.m_Talk_VTN = "Ta hiểu."
L22_1.m_Talk_SCN = "我知道。"
L22_1.m_Talk_DEU = "Das weiß ich."
L22_1.m_Talk_FRA = "J'en suis conscient."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 5100201
L23_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "GOD_NPC_NANAHARA2_NULL"
L23_1.m_Talk_KOREA = "우리 같은 존재는 인간처럼 한 번 품은 감정을 망각하지 못하지."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "我らのような存在は人間のように一度胸に抱いた感情を忘却できぬ。"
L23_1.m_Talk_ENG = "Being who we are, we do not forget feelings once embraced, unlike humans."
L23_1.m_Talk_TWN = "像我們這類的存在，一旦投入感情便無法遺忘。"
L23_1.m_Talk_THA = "อันสิ่งที่เราต่างเป็น ย่อมมิอาจลืมความรู้สึกซึ่งครั้งหนึ่งเคยถูกโอบกอด แต่มนุษย์หาเป็นไม่"
L23_1.m_Talk_VTN = "Những giống loài như chúng ta, chúng ta không quên được cảm xúc một khi đã từng trải qua, không giống như con người."
L23_1.m_Talk_SCN = "像我们这样的存在，一旦投入感情便无法遗忘。"
L23_1.m_Talk_DEU = "Wesen wie wir können, genau wie Menschen, die Gefühle nicht vergessen, die wir einst verspürt haben."
L23_1.m_Talk_FRA = "Toi, moi, et tous les autres de notre espèce... nous n'oublions pas."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "NANAHARA2_ACT2_INTERLUDE1@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 5100201
L24_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "GOD_NPC_NANAHARA2_NULL"
L24_1.m_Talk_KOREA = "그렇기에, 한 차례 인간을 증오해버리면 역신이 되고 마는 것이야."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "だからこそ、一度人間を憎み始めると疫病神になってしまうのだ。"
L24_1.m_Talk_ENG = "Thus, hatred towards humans turns us into Plague Gods."
L24_1.m_Talk_TWN = "因此只要憎恨人類一次，就會成為瘟神。"
L24_1.m_Talk_THA = "และความชิงชังต่อมนุษย์ก็เปลี่ยนเราเป็นเทพภัยพิบัติไปเช่นนั้นเอง"
L24_1.m_Talk_VTN = "Do đó, sự thù hận với con người biến chúng ta thành Thần Bệnh Dịch."
L24_1.m_Talk_SCN = "因此对人类的那个憎恨，会使我们成为瘟神。"
L24_1.m_Talk_DEU = "Deshalb wird man, wenn man die Menschen hasst, zu einem Gott der Verwesung."
L25_1 = "Et c'est cette haine qui t'a transformé. En Dieu du Fléau."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "NANAHARA2_ACT2_INTERLUDE1@25#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 25
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5100201
L25_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "욕망에 더럽혀지기 전에, 내가 그 영혼들을 거두어 가려는 것 뿐이다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "欲望にまみれてしまう前に、我がその魂を摘みとろうというだけだ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I am merely reaping their souls before they are further tainted by temptation."
L25_1.m_Talk_ENG = L26_1
L26_1 = "我只是在他們墮落前收走他們的靈魂而已。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ข้าเพียงจักเก็บเกี่ยวดวงดวงวิญญาณของพวกมันก่อนจะแปดเปื้อนซึ่งมลทินแห่งกิเลสตัณหา"
L25_1.m_Talk_THA = L26_1
L26_1 = "Ta chỉ gặt hái linh hồn chúng trước khi chúng bị ô nhiễm bởi sự cám dỗ mà thôi."
L25_1.m_Talk_VTN = L26_1
L26_1 = "我只是想在他们被欲望玷污之前，收走那些灵魂罢了。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich ernte lediglich ihre Seelen, bevor sie noch mehr von der Versuchung befleckt werden."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Tu te trompes. Tout ce que je fais, c'est moissonner leurs âmes avant que celles-ci ne soient souillées par la cupidité."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
