L38_1.m_fTalkTime = 0.03
L39_1 = "安心しなさい。ここは家よ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Rest assured. We're home."
L38_1.m_Talk_ENG = L39_1
L39_1 = "沒事了，是我們把你帶回來的。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ทำใจให้สบายนะ เราอยู่บ้านแล้ว"
L38_1.m_Talk_THA = L39_1
L39_1 = "Yên tâm đi. Chúng ta ở nhà rồi."
L38_1.m_Talk_VTN = L39_1
L39_1 = "别担心，我带你回家了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Sei beruhigt. Wir sind zuhause."
