L40_1 = "남동방 중대의 사람들은…… 어떻게 됐습니까?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "南東軍中隊の方たちは……どうなったのですか？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "The troops in Southeast Division... What happened to them?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "東南方中隊……他們人呢？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "กองกำลังของกองพลอาคเนย์ล่ะคะ... เกิดอะไรขึ้นกับพวกเขา?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Binh lính ở Sư Đoàn Đông Nam... Chuyện gì đã xảy ra với họ?"
