L40_1 = "东南部中队的人……怎么样了？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Die Soldaten der Südöstlichen Division ... Was ist mit ihnen passiert?"
L39_1.m_Talk_DEU = L40_1
