L41_1 = "R"
L40_1.m_Pos = L41_1
L41_1 = "우리가 도착했을 땐 이미 늦었더구나."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "私たちが着いた頃にはもう遅かった。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "We were too late."
