L41_1 = "我們到的時候已經為時已晚。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "พวกเราไปไม่ทันการณ์"
L40_1.m_Talk_THA = L41_1
L41_1 = "Bọn chị đã tới quá trễ."
L40_1.m_Talk_VTN = L41_1
L41_1 = "我们到那里时已经太迟了。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Es war bereits zu spät, als wir ankamen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Malheureusement, je n'ai pas pu arriver à temps."
