L43_1 = "L"
L42_1.m_Pos = L43_1
L43_1 = "제가 가문연합의 사람들을 지키지 못해서……"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "連合の方たちを守れず……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I failed to protect the people in our Alliance..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我沒能保護家族聯盟的人……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ข้าปกป้องผู้คนในสมาพันธ์ของเราไว้ไม่ได้..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Em đã không thể bảo vệ mọi người trong Liên Minh chúng ta..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我没能保护好家族联盟的人……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich war nicht in der Lage die Menschen in unserer Familienallianz zu schützen ..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Tout est de ma faute, je n'ai pas réussi à les protéger..."
L42_1.m_Talk_FRA = L43_1
