L44_1 = "R"
L43_1.m_Pos = L44_1
L44_1 = "그런 자책은 아직 해선 안 돼."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "まだ自分を責めるには早いわ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "You shouldn't wallow in self-pity just yet."
L43_1.m_Talk_ENG = L44_1
L44_1 = "你先別自責，"
L43_1.m_Talk_TWN = L44_1
L44_1 = "อย่าเพิ่งมัวเมาไปในความสมเพชตัวเองเช่นนั้นเลย"
L43_1.m_Talk_THA = L44_1
L44_1 = "Đừng tự dằn vặt nữa."
L43_1.m_Talk_VTN = L44_1
L44_1 = "你先别自责。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Mach dir jetzt noch keine Vorwürfe deswegen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Arrête, Chifuyu. Tu ne peux pas continuer de te blâmer ainsi éternellement."
L43_1.m_Talk_FRA = L44_1
