L44_1.m_CharStrID = L45_1
L45_1 = "R"
L44_1.m_Pos = L45_1
L45_1 = "그들이 무엇 때문에 그런 화를 당했는지 알아내고, 그 원흉을 해결하기 전까지는 감정에 휩쓸리지 말아야 한다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "彼らが何のためにそのようになったのかを明かし、その元凶を解決する前までは感情に流されてはいけない。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You must keep composed to find out and resolve what caused this tragedy."
L44_1.m_Talk_ENG = L45_1
L45_1 = "在我們釐清他們遇害的原因，並且解決掉兇手之前，不能陷入情緒當中。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เจ้าต้องตั้งสติเพื่อตามหาและแก้ไขสาเหตุที่ทำให้เกิดโศกนาฏกรรมนี้"
L44_1.m_Talk_THA = L45_1
L45_1 = "Em phải thật bình tĩnh để điều tra và giải quyết thứ đã gây ra thảm kịch này."
L44_1.m_Talk_VTN = L45_1
L45_1 = "在查出他们是遇害的原因，解决掉事端的元凶之前，都不可以被感情所左右。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Lass dich nicht von deinen Gefühlen mitreißen, solange du nicht herausgefunden und aufgeklärt hast, was diese Tragödie verursacht hat."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Nous devons garder notre sang-froid, et résoudre cette tragédie. Ne nous laissons pas emporter par nos sentiments."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
