L51_1 = "พักเถอะ เราจะจัดการต่อเอง"
L50_1.m_Talk_THA = L51_1
L51_1 = "Cứ nghỉ ngơi đi. Từ giờ để bọn chị lo."
L50_1.m_Talk_VTN = L51_1
L51_1 = "继续休息吧，剩下的事情就交给我们来解决。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ruh dich aus. Ab jetzt werden wir uns darum kümmern."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Repose-toi, je m'occupe du reste."
L50_1.m_Talk_FRA = L51_1
