L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "네 몸상태는 지금 그리 좋지 않아. 내 말을 듣도록 하렴."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "あなたの体の具合はそこまで良くないの。私の言うことを聞きなさい。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You are not well right now. Please do as I say."
L2_1.m_Talk_ENG = L3_1
L3_1 = "你現在的身體狀況不太好，聽我的話。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "อาการเจ้ายังไม่ดีนะ โปรดทำตามที่ข้าบอกเถอะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Bây giờ em chưa khỏe. Cứ làm như chị nói đi."
L2_1.m_Talk_VTN = L3_1
L3_1 = "你现在的身体状态不太好，听我的话。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Dir geht es im Moment nicht so gut. Bitte tu, was ich sage."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Tu as besoin de repos, Chifuyu. Fais ce que je te dis, s'il te plaît."
L2_1.m_Talk_FRA = L3_1
