L5_1.m_CharStrID = L6_1
L6_1 = "L_M_I"
L5_1.m_Pos = L6_1
L6_1 = "저는 당주님의 호위입니다. 고작 이런 상처 때문에 당주님을 혼자 둘 수는……!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "私は当主の護衛です。この程度の怪我で当主をお一人にするわけには……！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But I am your bodyguard. I cannot leave you because of a minor wound...!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "我是堂主的護衛，怎麼能因為一點小傷就放堂主獨自……！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แต่ข้าเป็นผู้คุ้มกันของท่านนะคะ ข้าจะปล่อยท่านไปคนเดียวด้วยแผลเล็กน้อยแค่นี้ไม่ได้หรอก...!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nhưng em là hộ vệ của chị. Em không thể để chị phải chịu bất kỳ tổn hại nào ...!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "我是家主的护卫，不能因为这点小伤就让家主您一个人……！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Aber ich bin doch deine Leibwächterin. Ich kann dich wegen einer kleinen Wunde nicht einfach alleine ...!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais je suis votre garde du corps ! Ce n'est pas une petite blessure qui va... !"
L5_1.m_Talk_FRA = L6_1
