L9_1 = "L"
L8_1.m_Pos = L9_1
L9_1 = "제가 당주님보다 약한 호위이기 때문인가요?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "私が当主より弱い護衛だからですか？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Is it because I am weaker than you?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "是因為我這個護衛比堂主還弱嗎？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เพราะข้าอ่อนแอกว่าหรือคะ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Có phải vì em yếu hơn chị không?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "是因为我这个护卫比家主您还弱吗？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Liegt es daran, dass ich schwächer bin als du?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Est-ce parce que je suis plus faible que vous ?"
