L10_1.m_fTalkTime = 0.03
L11_1 = "そんな理由ではないわ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "No. That is not the reason why."
L10_1.m_Talk_ENG = L11_1
L11_1 = "不是的。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ไม่ เหตุผลไม่ใช่เพราะแบบนั้น"
L10_1.m_Talk_THA = L11_1
L11_1 = "Không. Đó không phải là lý do."
L10_1.m_Talk_VTN = L11_1
L11_1 = "不是那样的。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Nein, es ist nicht deswegen."
