L11_1.m_Face = L12_1
L12_1 = "CUTSCENE_LONELY"
L11_1.m_StartBGMFileName = L12_1
L12_1 = "CHIFUYU_NANA_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "그렇다면 왜…… 연합원들이 모두 움직일 때 저만 데려가지 않으신 겁니까?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "それならなぜ……連合員全員が動く時に私だけ置いて行かれたのですか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Then why... Why won't you take me with you when the other members are?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "那為什麼……聯盟全員出動時，卻只扔下我一個人？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ถ้าอย่างนั้นเพราะเหตุใดคะ... ทำไมท่านพาสมาชิกคนอื่นไปแต่ไม่พาข้าไปด้วย?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Vậy thì tại sao chứ... Tại sao chị không đưa em đi cùng chị khi những thành viên khác được đi?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "那为什么……联盟成员出动的时候，唯独不带我去？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Warum nimmst du mich dann nicht auch mit, wenn alle anderen Mitglieder dir folgen dürfen?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Alors pourquoi... pourquoi ne me prenez-vous pas à vos côtés ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "NANAHARA2_ACT2_INTERLUDE1@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
