L13_1 = "CHIFUYU_NANA_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "휴가를 명목으로 저를 혼자 떨어트린 이유가 무엇인가요?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "休みの名目で私を一人だけ引き離した理由は何ですか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "What is your reason for using my resting as an excuse for leaving me behind?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "用休假的名義甩開我的理由是什麼？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "เหตุใดใช้การพักของข้าเป็นข้ออ้างเพื่อทิ้งข้าไว้กันคะ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Lý do cho việc chị sử dụng cái cớ em phải nghỉ ngơi để bỏ lại em là gì?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "借休假之名，甩开我一个人的理由是什么？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Aus welchem ​​Grund willst du mich schon wieder unter dem Vorwand der „Erholung“ zurückzulassen?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Pourquoi me laisser derrière en prétextant que j'ai besoin de me reposer ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "NANAHARA2_ACT2_INTERLUDE1@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
