L15_1 = "我是堂主的護衛！我在意的……！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ข้าเป็นคนคุ้มกันของท่านนะคะ ท่านหญิงนานะฮาระ! ที่ข้าต้องการก็แค่–!"
