L15_1 = "Em là hộ vệ của chị, Tiểu Thư Nanahara! Mọi điều em muốn chỉ là-!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "我是家主的护卫！我所希望的……！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich bin deine Leibwächterin, Anführerin! Ich will dich doch nur beschützen ...!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Je suis votre garde du corps, Dame Nanahara ! Votre sécurité est ma raison de viv... !"
