L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "의사에게 맡기라고 하셨지만, 역시 내가 치료하는 편이……"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "医者に任せるようにと言われたけど、やはり私が治療した方が……"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I know I told you to see a doctor, but perhaps it will be better for me to treat it myself..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "雖然說要交給醫生處理，但還是我來……"
L18_1.m_Talk_TWN = L19_1
L19_1 = "จริงอยู่ที่ข้าบอกให้เจ้าไปพบแพทย์ แต่บางทีถ้าข้ารักษาเองอาจจะดีกว่า..."
L18_1.m_Talk_THA = L19_1
L19_1 = "Chị nhớ chị đã bảo em đi khám bác sĩ rồi, nhưng có lẽ để chị tự mình chữa trị giúp em sẽ tốt hơn..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "虽然说要交给医生处理，但还是我来治疗比较……"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ich habe dir zwar gesagt, du sollst einen Arzt aufsuchen, aber vielleicht sollte ich ihn einfach selbst behandeln ..."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Je sais que je t'ai dit d'aller voir un médecin, mais... peut-être que je ferais mieux de m'en occuper."
L18_1.m_Talk_FRA = L19_1
