L30_1 = "奈緒大人！堂主昏倒了！快找醫生……！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ท่านนาโอะคะ! ท่านหญิงนานะฮาระเป็นลมไปแล้วค่ะ! เราต้องการแพทย์...!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Cô Nao! Tiểu Thư Nanahara xỉu rồi! Chúng ta cần gọi bác sĩ...!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "奈绪大人！家主晕倒了！快点叫医生……！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Fräulein Nao! Die Anführerin ist ohnmächtig geworden! Wir brauchen schnell einen Arzt ...!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Madame Nao ! Dame Nanahara a perdu connaissance ! Vite, un médecin... !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "NANAHARA2_ACT2_INTERLUDE1@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5100201
L30_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
