L30_1.m_Face = "UNIT_HATE"
L31_1 = "FX_CUTSCEN_NOISE_RUSTLE_04"
L30_1.m_StartFXSoundName = L31_1
L31_1 = "DRAGON_NANAHARA_NULL_NULL"
L30_1.m_CharStrID = L31_1
