L30_1.m_Crash = 20
L31_1 = "시끄럽다, 꼬맹이!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "うるさい、小童！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Silence, Girl!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "吵死了，小鬼！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เงียบนะ ยัยเด็กนี่!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Yên nào, Cô Gái!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "吵死了，小鬼！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Halt den Rand, du kleine Göre!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Silence, gamine !"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NANAHARA2_ACT2_INTERLUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5100201
L31_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_SERIOUS"
L31_1.m_Face = L32_1
L32_1 = "DRAGON_NANAHARA_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "작은 당주, 능력으로 치유하지 말라고 일러뒀거늘. 왜 주의를 듣지 않은 게냐?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "チビ当主、能力で治癒するなと言ったはずじゃ。どうしてわしの言うことを聞かんのじゃ？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I told you to not use your powers to treat others, Ladychild. Why do you defy me?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "小堂主，我早就吩咐過你不要使用能力來治療，為什麼把我的話當耳邊風？！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ข้าบอกแล้วใช่มั้ยว่าอย่าใช้พลังไปรักษาผู้อื่น ท่านหญิงน้อย ไยยังดื้อดึง?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi đã bảo cô đừng dùng sức mạnh của mình để chữa trị cho ai nữa cơ mà, Tiểu Thư bé nhỏ. Tại sao cô chẳng chịu nghe lời?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "小家主，我早就吩咐过你不要用能力给别人治疗吧。为什么把我的话当耳旁风呢？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich habe dir doch gesagt, du sollst deine Kräfte nicht nutzen, um andere zu behandeln, zierliche Anführerin. Warum hast du nicht auf mich gehört?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Ne t'ai-je pas dit d'arrêter d'utiliser tes pouvoirs ainsi, la mioche ? Pourquoi cet entêtement ?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
