L34_1 = "NANAHARA2_ACT2_INTERLUDE1@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5100201
L33_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "UNIT_DESPAIR"
L33_1.m_Face = L34_1
L34_1 = "CHINATSU_NANA_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "죄송…… 합니다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "申し訳……ございません。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "My... apologies."
L33_1.m_Talk_ENG = L34_1
L34_1 = "對不……起。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ข้า... ขออภัยด้วยค่ะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi...xin lỗi."
L33_1.m_Talk_VTN = L34_1
L34_1 = "对不……起。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Tut mir leid."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mes excuses..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "NANAHARA2_ACT2_INTERLUDE1@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5100201
L34_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "CHINATSU_NANA_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "치후유의 상처가 너무 심해서 그냥 둘 수가 없었어요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "千冬の傷がひどすぎて放っておくわけにはいきませんでした。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Chifiyu's wounds were too grave to ignore."
L34_1.m_Talk_ENG = L35_1
L35_1 = "千冬的傷勢太嚴重，我沒辦法袖手旁觀。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "บาดแผลของชิฟุยุสาหัสเกินจะเพิกเฉย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Vết thương của Chifuyu quá nghiêm trọng, tôi không thể nào nhắm mắt cho qua."
L34_1.m_Talk_VTN = L35_1
L35_1 = "千冬伤得太重了，我不能就那样放着不管。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Chifuyus Wunden waren so schlimm, dass ich sie nicht einfach ignorieren konnte."
L34_1.m_Talk_DEU = L35_1
L35_1 = "La blessure de Chifuyu était trop grave, il fallait que je fasse quelque chose."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NANAHARA2_ACT2_INTERLUDE1@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5100201
L35_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "CHINATSU_NANA_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "하지만 전혀 치료가 되지 않는 것 같네요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ですがまったく治療できてないみたいです。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Nevertheless, it appears that my efforts were in vain."
L35_1.m_Talk_ENG = L36_1
L36_1 = "只是好像完全沒辦法進行治療？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "กระนั้น ก็กลายเป็นว่าความพยายามของข้ากลับสูญเปล่า"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tuy nhiên, có vẻ như những nỗ lực của tôi đều là vô ích."
L35_1.m_Talk_VTN = L36_1
L36_1 = "但是治疗好像完全没起作用。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aber es scheint überhaupt keine Heilung stattgefunden zu haben."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Pourtant, il semblerait que mes efforts ont été vains."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA2_ACT2_INTERLUDE1@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5100201
L36_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_DESPAIR"
L36_1.m_Face = L37_1
L37_1 = "DRAGON_NANAHARA_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "신의 피를 억지로 정화하려 들면 반발이 생기는 것이 당연하지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "神の血を無理やり浄化しようとすれば当然反動が来よう。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Of course you'll suffer the consequences for trying to purify divine blood."
L36_1.m_Talk_ENG = L37_1
L37_1 = "硬要淨化神的血液當然會產生反彈。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "พยายามชะล้างโลหิตเทวะเจ้าก็ย่อมต้องรับผลที่ตามมาเป็นธรรมดา"
L36_1.m_Talk_THA = L37_1
L37_1 = "Dĩ nhiên, cô sẽ phải chịu hậu quả nếu cố gắng thanh lọc dòng máu thần thánh."
L36_1.m_Talk_VTN = L37_1
L37_1 = "强行净化神之血，自然会受到反噬。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wenn man versucht, das Blut eines Gottes zwanghaft zu reinigen, ist es nur natürlich, dass es eine Gegenreaktion gibt."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Voilà le prix à payer pour avoir essayé de purifier du sang divin."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA2_ACT2_INTERLUDE1@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5100201
L37_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_SURPRISE"
L37_1.m_Face = L38_1
L38_1 = "CHIFUYU_NANA_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "신의 피……? 그게 무슨 말씀이신가요?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "神の血……？　それはどういうことですか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Divine blood...? I don't understand."
L37_1.m_Talk_ENG = L38_1
L38_1 = "神的血液……？什麼意思？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "โลหิตเทวะ...? ไม่เห็นเข้าใจเลยค่ะ..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Dòng máu thần thánh...? Tôi chẳng hiểu gì cả."
L37_1.m_Talk_VTN = L38_1
L38_1 = "神之血……？这话是什么意思？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Das Blut eines Gottes ...? Was meinen Sie denn damit?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Du sang divin... ? Je ne comprends pas."
L37_1.m_Talk_FRA = L38_1
