L41_1 = "NANAHARA2_ACT2_INTERLUDE1@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 5100201
L40_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "UNIT_DESPAIR"
L40_1.m_Face = L41_1
L41_1 = "DRAGON_NANAHARA_NULL_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "R"
L40_1.m_Pos = L41_1
L41_1 = "하야미의 제자. 하바키 일당들이 널 붙잡았을 때 무슨 짓을 했는지 기억하느냐?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "速水の弟子よ、覇吐の連中がお主を捕まえた時何をしたか覚えているか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Apprentice of Hayami, do you remember what Habaki's men did to you the day you were caught?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "速水的徒弟，你還記得幅木他們抓到你時，對你做了什麼嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ศิษย์แห่งฮายามิ จำได้หรือไม่ว่าคนของฮาบากิทำอะไรกับเจ้าตอนที่เจ้าโดนลักพาตัวไป?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đồ đệ của Hayami, cô có nhớ người của Habaki đã làm gì với cô vào ngày cô bị bắt cóc không?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "速水的弟子，幅木他们抓到你时对你做了什么，你还记得吗？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Hayamis Lehrling, erinnerst du dich daran, was Habakis Männer dir an dem Tag angetan haben, als du gefangen wurdest?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Te souviens-tu de ce que les hommes de Habaki t'ont fait quand ils t'ont capturée, disciple de Hayami ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "NANAHARA2_ACT2_INTERLUDE1@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5100201
L41_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "UNIT_DESPAIR"
L41_1.m_Face = L42_1
L42_1 = "CHIFUYU_NANA_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "L"
L41_1.m_Pos = L42_1
L42_1 = "주삿바늘과…… 피가 끓는 듯한 통증 이후로는…… 잘 기억이 나지 않습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "注射の針と……血が沸くような苦しみの後は……よく覚えておりません。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I remember needles... and a burning sensation in my veins... The rest is all hazy."
L41_1.m_Talk_ENG = L42_1
L42_1 = "他們對我進行注射……接著我感受到一股彷彿血液沸騰般的痛楚……之後的事就完全不記得。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ข้าจำได้ว่ามีเข็ม... แล้วก็รู้สึกเหมือนมีเพลิงลุกไหม้ในกระแสเลือด... นอกนั้นก็เลือนรางนักค่ะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi nhớ những mũi kim tiêm...và cảm giác nóng cháy trong huyết quản...Còn lại thì hoàn toàn mơ hồ."
L41_1.m_Talk_VTN = L42_1
L42_1 = "针头……血液沸腾一般的疼痛……之后的事我就不记得了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich erinnere mich an Nadeln ... und ein brennendes Gefühl in meinen Adern ... An den Rest kann ich mich nicht wirklich erinnern."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Il y avait une aiguille... et une sensation de brûlure dans mes veines... tout le reste est flou."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
