L44_1 = "UNIT_SURPRISE"
L43_1.m_Face = L44_1
L44_1 = "CHINATSU_NANA_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "그자들이 치후유에게 무슨 짓을 했는지 아시나요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "あの者たちが千冬に何をしたのかご存じなのですか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Do you know what they did to Chifuyu?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "您知道他們對千冬做了什麼嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "รู้หรือไม่ว่าพวกนั้นทำอะไรเจ้า ชิฟุยุ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Em có biết họ đã làm gì với em không, Chifuyu?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "您知道他们对千冬做了什么吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Wissen Sie, was sie Chifuyu angetan haben?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Vous savez ce qu'ils ont fait à Chifuyu ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "NANAHARA2_ACT2_INTERLUDE1@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
