L45_1 = "DRAGON_NANAHARA_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "안 그래도 녀석의 혈액을 분석하고 오는 길이다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ちょうどそいつの血液を分析してきたところじゃ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I am on my way back from analyzing her blood."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我來就是要分析這傢伙的血液的。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ข้ากลับมาจากการวิเคราะห์เลือดนาง"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi đang trên đường trở về sau khi phân tích máu của cô ấy."
L44_1.m_Talk_VTN = L45_1
L45_1 = "我正好刚分析完她的血液。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Ich habe ihr Blut analysiert."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Eh bien, je viens justement d'obtenir les résultats du labo."
L44_1.m_Talk_FRA = L45_1
