L46_1 = "DRAGON_NANAHARA_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "그 무쇠머리 놈이 내 피를 빼돌려 녀석의 몸에 넣은 모양이더구나."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あの機械頭がわしの血を抜いてそいつの体に入れたようじゃ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "It appears that ironhead stole my blood and injected it into her."
L45_1.m_Talk_ENG = L46_1
L46_1 = "那個鐵面男可能把我的血液注射到這傢伙的體內了。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "กลายเป็นว่าไอ้หัวเหล็กนั่นมันขโมยเลือดข้าไปฉีดใส่นาง"
L45_1.m_Talk_THA = L46_1
L46_1 = "Có vẻ như gã đầu sắt đã đánh cắp máu của tôi và tiêm nó vào cô ấy"
L45_1.m_Talk_VTN = L46_1
L46_1 = "那个铁面男好像偷了我的血液，注射进了她的身体里。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Es scheint, dass dieser maskierte Fremde mein Blut gestohlen und es ihr injiziert hat."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Il semblerait que ce déglingué au masque ait volé mon sang, et qu'il l'ait injecté dans ses veines."
L45_1.m_Talk_FRA = L46_1
