L49_1 = "실험 관찰 결과…… 고통을 호소하는 것 외에 긍정적인 변화는 보이지 않는군."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "実験観察の結果……苦痛を訴える以外にポジティブな変化は見られないな。"
