L2_1 = "의식을 잃기 전, 그자가 이걸 실험이라고 부르는 것을 들었습니다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "意識を失う前に、あの者がこれを実験と呼んでいるのを聞きました。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Before I lost consciousness, I heard him calling this \"an experiment\"."
L1_1.m_Talk_ENG = L2_1
L2_1 = "我失去意識之前，聽到他說這是個實驗。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ก่อนจะหมดสติไป ข้าได้ยินพวกเขาเรียกมันว่า \"การทดลอง\""
L1_1.m_Talk_THA = L2_1
L2_1 = "Trước khi bất tỉnh, tôi nghe hắn gọi đây là \"một cuộc thử nghiệm\"."
L1_1.m_Talk_VTN = L2_1
L2_1 = "在我失去意识前，我听到那人将这个称为实验。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Bevor ich das Bewusstsein verlor, hörte ich, wie er dies „ein Experiment“ nannte."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Avant de perdre connaissance, je l'ai entendu parler d'un « test »..."
