L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "あの数の兵士をたかが実験のために捧げたわけだからのう。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Sacrificing all those men just for an experiment..."
L5_1.m_Talk_ENG = L6_1
L6_1 = "犧牲這麼多兵力，只為了一個區區的實驗。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "สังเวยคนทั้งหมดนั่นแค่เพื่อการทดลองหนึ่ง..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Hy sinh tất cả bọn họ chỉ vì một cuộc thử nghiệm..."
L5_1.m_Talk_VTN = L6_1
L6_1 = "只是为了一个实验，就牺牲了那么多自己的士兵。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Alle diese Soldaten nur für ein Experiment zu opfern ..."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Tous ces sacrifices pour une simple expérience..."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
