L6_1.m_Face = L7_1
L7_1 = "CHIFUYU_NANA_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "바치다니…… 그게 무슨 뜻입니까?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "捧げる……それはどういう意味ですか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Sacrifice? What do you mean by that?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "犧牲……這是什麼意思？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "สังเวย? หมายความว่ายังไงกันคะ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Hy sinh? Ý cô là sao?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "牺牲……那是什么意思？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "„Opfern“? Was meinen Sie damit?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Sacrifices ? Que voulez-vous dire ?"
L6_1.m_Talk_FRA = L7_1
