L10_1 = "NANAHARA2_ACT2_INTERLUDE1@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5100201
L9_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "UNIT_DESPAIR"
L9_1.m_Face = L10_1
L10_1 = "DRAGON_NANAHARA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "R"
L9_1.m_Pos = L10_1
L10_1 = "네 녀석이 의식을 잃고, 명부검을 휘둘러 그것들을 죄다 베어버렸거든."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "お主が意識を失い、冥府剣を振り回してあやつらを全部斬ってしまったのじゃ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "When you lost consciousness, you swung your Nether God’s Sword and slashed through everyone there."
L9_1.m_Talk_ENG = L10_1
L10_1 = "你失去意識後，拿著冥府劍把人家都給斬了。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ตอนที่สิ้นสติ เจ้ากวัดแกว่งดาบฟาดฟันทุกคนที่นั่น"
L9_1.m_Talk_THA = L10_1
L10_1 = "Khi cô mất trí, cô vung Thanh Kiếm Của Thần Âm Ty và giết chết mọi người ở đó."
L9_1.m_Talk_VTN = L10_1
L10_1 = "你失去意识后，用冥剑把他们全都给杀了。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Als du das Bewusstsein verlorst, hast du das Schwert des Gottes des Jenseits geschwungen und sie alle aufgeschlitzt."
L9_1.m_Talk_DEU = L10_1
L10_1 = "En perdant connaissance, tu as donné un grand coup avec l'épée du Néant. Et tu as coupé tout le monde."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NANAHARA2_ACT2_INTERLUDE1@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 5100201
L10_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "CHIFUYU_NANA_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "L"
L10_1.m_Pos = L11_1
L11_1 = "제가…… 말입니까? 하지만 어떻게?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "私が……ですか？　しかし、どうやって？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I... did what? But how?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "你說……我？怎麼可能？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ข้า... ทำอะไรนะคะ? ทำไมเป็นเช่นนั้น?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tôi...đã làm gì cơ? Nhưng sao lại thế?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "我……吗？可是我怎么？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich habe was gemacht? Aber wie?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "J'ai fait quoi ? Mais comment... ?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NANAHARA2_ACT2_INTERLUDE1@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 5100201
L11_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "DRAGON_NANAHARA_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "R"
L11_1.m_Pos = L12_1
L12_1 = "내가 가진 명부신의 피가 네놈의 영혼을 파고들어 검을 움직일 힘을 준 것이지."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "わしの持つ冥府の神の血がお主の魂に入り込み、刀を振るう力を与えたのじゃ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "The Nether God's blood has permeated your soul, endowing you with the capacity to wield that sword."
L11_1.m_Talk_ENG = L12_1
L12_1 = "我身上的冥府神血液滲入你的靈魂，使你有力量可以揮動冥府劍。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "โลหิตยมราชแผ่ซ่านไปทั่ววิญญาณเจ้า มอบความสามารถในการกวัดแกว่งดาบนั่นแก่เจ้า"
L11_1.m_Talk_THA = L12_1
L12_1 = "Máu của Thần Âm Ty đã thấm vào linh hồn cô, ban cho cô khả năng vung thanh kiếm đó."
L11_1.m_Talk_VTN = L12_1
L12_1 = "是我身上的冥神之血渗入了你的灵魂，给了你挥剑的力量吧。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Das Blut des Gottes des Jenseits hat deine Seele durchdrungen und dir die Fähigkeit verliehen, dieses Schwert zu führen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Le sang du Dieu du Néant a imprégné ton âme, te permettant de manier son épée."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "NANAHARA2_ACT2_INTERLUDE1@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5100201
L12_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "UNIT_SERIOUS"
L12_1.m_Face = L13_1
L13_1 = "CHIFUYU_NANA_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "L"
L12_1.m_Pos = L13_1
L13_1 = "그렇다면…… 나오님의 피가 명부신과 같은 힘을 얻게 한다는 말씀입니까?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ならば……ナオ様の血が冥府の神のような力を与えてくれるということですか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Then... are you saying that your blood has the same properties as those of the Nether God?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "意思是……奈緒大人的血讓我獲得與冥府神一樣的力量嗎？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "เช่นนั้นแล้ว... ท่านจะบอกว่าเลือดของท่านมีคุณสมบัติแบบเดียวกับของยมราชหรือคะ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Vậy thì ... cô đang nói rằng máu của cô có cùng đặc tính với Thần Âm Ty sao?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "那……您的意思是您的血会让人获得和冥神一样的力量吗？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Dann ... meinen Sie also, dass Ihr Blut die gleichen Eigenschaften hat wie das vom Gott des Jenseits?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Mais alors... votre sang a les mêmes propriétés que celui du Dieu du Néant ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "NANAHARA2_ACT2_INTERLUDE1@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5100201
L13_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_HATE"
L14_1 = "DRAGON_NANAHARA_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "R"
L13_1.m_Pos = L14_1
L14_1 = "이번엔 운이 좋았을 뿐이야. 인간의 신체와 영혼은 보통 환상종의 피를 감당하지 못해."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "今回は運が良かっただけじゃ。人間の体と魂は普通、幻想種の血に耐えられん。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You were lucky this time. A human's body and soul normally cannot withstand the blood of Bygones."
L13_1.m_Talk_ENG = L14_1
L14_1 = "這次只能算你運氣好，人類的身體和靈魂是無法負荷夢幻類的血的。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เจ้าโชคดีไปนะคราวนี้ ปกติแล้วร่างกายกับวิญญาณของมนุษย์ต้านทานโลหิตของบายกอนไม่ได้หรอก"
L13_1.m_Talk_THA = L14_1
L14_1 = "Lần này cô may mắn đấy. Cơ thể và linh hồn con người vốn không thể chịu nổi máu của Bygone."
L13_1.m_Talk_VTN = L14_1
L14_1 = "这次只是运气好罢了。人类的身体和灵魂通常无法承受幻想种的血。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Dieses Mal hatten Sie Glück. Körper und Seele eines Menschen können dem Blut eines Vergangenen normalerweise nicht standhalten."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Tu as eu de la chance pour cette fois. En temps normal, le corps d'un être humain ne devrait pas pouvoir supporter le sang des Chimères."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "NANAHARA2_ACT2_INTERLUDE1@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5100201
L14_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "DRAGON_NANAHARA_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "R"
L14_1.m_Pos = L15_1
L15_1 = "제아무리 나나하라의 혈통이라 해도, 신의 피에 취하면 영혼이 잡아 먹히고 만다."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "いくら七原の血統とは言え、神の血に酔えば魂が喰われてしまう。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Even if you are of Nanahara blood, divine blood tends to eat away at your soul."
L14_1.m_Talk_ENG = L15_1
L15_1 = "即使是七原的血統，在神的血液裡靈魂也會被吞噬掉。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ต่อให้เจ้ามีโลหิตของนานะฮาระ โลหิตเทวะก็ยังอาจกัดกินดวงวิญญาณเจ้าสิ้นอยู่ดี"
L14_1.m_Talk_THA = L15_1
L15_1 = "Ngay cả khi cô có dòng máu Nanahara, dòng máu thần thánh vẫn sẽ co xu hướng ăn mòn linh hồn cô."
L14_1.m_Talk_VTN = L15_1
L15_1 = "即使是七原的血统，沉醉于神之血的话，灵魂也会被吞噬。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Selbst wenn das Blut der Nanahara durch deine Adern fließt, neigt göttliches Blut dennoch dazu, die Seele zu verschlingen."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Tu as beau être une descendante de la lignée Nanahara, le sang divin devrait corrompre ton âme..."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "NANAHARA2_ACT2_INTERLUDE1@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5100201
L15_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "UNIT_IDLE"
L15_1.m_Face = L16_1
L16_1 = "CHIFUYU_NANA_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "L"
L15_1.m_Pos = L16_1
L16_1 = "하지만…… 그 피의 힘을 잠시나마 빌릴 수 있다면, 예견에 어울리는 무사가 될 수 있겠지요."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ですが……その血の力をしばし借りることができれば、予言に相応しい武士になれます。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "But then... If I can borrow that power for a while, I could become the warrior that the foresight says."
L15_1.m_Talk_ENG = L16_1
L16_1 = "但……若是能暫時借用血的力量，那我就可以成為預言中的武士吧？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แต่ถ้าเช่นนั้น... หากข้าสามารถยืมพลังนั่นมาได้สักห้วง ข้าก็จะเป็นนักรบตามคำพยากรณ์ได้"
L15_1.m_Talk_THA = L16_1
L16_1 = "Nhưng sau đó... Nếu tôi có thể mượn sức mạnh đó trong một thời gian, tôi có thể trở thành chiến binh trong tiên đoán."
L15_1.m_Talk_VTN = L16_1
L16_1 = "可是……如果可以暂时借助血的力量，应该就能成为预言中的武士吧。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Aber ... wenn ich mir diese Kraft für eine Weile leihen könnte, könnte ich die Kriegerin werden, von der in der Voraussicht gesprochen wurde."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Mais alors... si je peux emprunter ce pouvoir, même temporairement, je pourrais devenir cette guerrière mentionnée dans la vision !"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NANAHARA2_ACT2_INTERLUDE1@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 5100201
L16_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "UNIT_SERIOUS"
L16_1.m_Face = L17_1
L17_1 = "CHIFUYU_NANA_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "L"
L16_1.m_Pos = L17_1
L16_1.m_Crash = 20
L17_1 = "그렇게 해서라도 제가 역신베기를 완성할 수 있다면……!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "そうしてでも私が大蛇薙剣を完成できるとしたら……！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "If that is what it takes for me to complete Orochinagi...!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "那我或許就可以完成瘟神斬……！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ถ้านั่นคือสิ่งที่ข้าต้องทำเพื่อให้โอโรจินางิสมบูรณ์ละก็...!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nếu đó là những gì tôi cần để hoàn thành Orochinagi...!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "那样的话我或许就能完成瘟神斩……！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Wenn es das ist, was ich brauche, um das Orochinagi zu vollenden ...!"
L16_1.m_Talk_DEU = L17_1
