L21_1[2] = L23_1
L19_1[L20_1] = L21_1
L20_1 = "영생을 탐하여 신의 피를 노린 인간들의 말로를 배우지 못했느냐!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "永生を貪り神の血を狙った人間の末路を学ばなかったのか！"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Have you not learned from those fools who tried to become immortal with divine blood?!"
L19_1.m_Talk_ENG = L20_1
L20_1 = "那些貪圖永生覬覦神血液的人下場，沒能讓你學到教訓嗎！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "นี่เจ้ามิได้เรียนรู้อะไรจากพวกไร้ปัญญาที่พยายามเป็นอมตะด้วยโลหิตเทวะเลยหรือไร?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cô vẫn chưa học được gì từ những kẻ ngu cố gắng trở thành bất tử bằng cách sử dụng dòng máu thần thánh sao?!"
L19_1.m_Talk_VTN = L20_1
L20_1 = "那些因为贪图永生觊觎神之血的人类的下场，难道你还没有见识够吗！"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Hast du denn gar nichts von diesen Idioten gelernt, die versuchten, mithilfe des göttlichen Blutes unsterblich zu werden?!"
L19_1.m_Talk_DEU = L20_1
L20_1 = "N'as-tu pas retenu la leçon ? As-tu oublié la tragédie de tes ancêtres que la quête d'immortalité a rendus fous ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "NANAHARA2_ACT2_INTERLUDE1@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5100201
L20_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "DRAGON_NANAHARA_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "다시 한번 이런 힘을 받아들였다간, 네놈은 피에 영혼이 삼켜진 빈 껍데기가 될 게다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "再びこのような力を受け入れようものなら、血に魂を喰いつくされ抜け殻しか残らなくなる。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "If you inject yourself with this blood again, you will become a soulless, empty shell."
L20_1.m_Talk_ENG = L21_1
L21_1 = "要是再次接受這股力量，你就會成為靈魂遭血液吞噬的空殼子。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "หากฉีดโลหิตนั่นเข้าร่างเจ้าอีกหน เจ้าได้กลายเป็นเปลือกกลวงเปล่าไร้วิญญาณแน่"
L20_1.m_Talk_THA = L21_1
L21_1 = "Nếu cô tiêm loại máu này lần nữa, cô sẽ trở thành một cái vỏ vô hồn, trống rỗng."
L20_1.m_Talk_VTN = L21_1
L21_1 = "如果再接受一次这样的力量，你的灵魂就会被神之血吞噬，变成一具空壳。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wenn du dir dieses Blut erneut injizierst, wirst du zu einer seelenlosen, leeren Hülle."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Si tu continues de t'injecter ce sang, ton âme s'effacera peu à peu et tu ne seras plus que l'ombre de toi-même."
L20_1.m_Talk_FRA = L21_1
