L24_1.m_CharStrID = L25_1
L25_1 = "R"
L24_1.m_Pos = L25_1
L25_1 = "하바키 놈을 잡아들일 때까지 신기를 완성하는 일은 잠시 보류다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "覇吐を捕まえるまで神器を完成させる仕事はしばし保留とする。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Until Habaki is captured, completing the Sacred Treasure is on hold."
L24_1.m_Talk_ENG = L25_1
L25_1 = "在抓到幅木前，完成神器的計畫先暫停。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ตราบใดยังจับตัวฮาบากิไม่ได้ เรื่องสร้างสมบัติศักดิ์สิทธิ์ให้เสร็จสิ้นก็ต้องพักไว้ก่อน"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cho đến khi bắt được Habaki, việc hoàn thiện Thần Khí sẽ phải tạm dừng."
L24_1.m_Talk_VTN = L25_1
L25_1 = "在抓到幅木那家伙之前，完成神器的事先放一放。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Die Vollendung des Orochinagi wird vorübergehend auf Eis gelegt, bis Habaki gefangen wurde."
L24_1.m_Talk_DEU = L25_1
L25_1 = "La lame sacrée peut attendre. Pour le moment, nous devons capturer Habaki."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "NANAHARA2_ACT2_INTERLUDE1@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5100201
L25_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "DRAGON_NANAHARA_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "R"
L25_1.m_Pos = L26_1
L26_1 = "그러니 네놈도 그전까진 독단으로 행동하지 마라, 하야미의 제자."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "だから、お主もそれまでは独断で行動するでない、速水の弟子。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "So, until then, apprentice of Hayami, no acting on your own will."
L25_1.m_Talk_ENG = L26_1
L26_1 = "在那之前你也不准擅自行動，知道嗎，速水的徒弟？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เช่นนั้นแล้ว กว่าจะถึงตอนนั้น ศิษย์แห่งฮายามิเอ๋ย ห้ามทำอะไรตามใจตนเด็ดขาด"
L25_1.m_Talk_THA = L26_1
L26_1 = "Cho đến lúc đó, đồ đệ của Hayami, đừng tự hành động theo ý mình nữa."
L25_1.m_Talk_VTN = L26_1
L26_1 = "在那之前你不可以擅自行动，知道了吗，速水的弟子？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Also handele bis dahin nicht auf eigene Faust, Hayamis Lehrling."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Jusque-là... tu es priée de te tenir à carreau, disciple de Hayami."
L25_1.m_Talk_FRA = L26_1
