L30_1.m_Face = "UNIT_HATE"
L31_1 = "DRAGON_NANAHARA_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "나 참. 가문연합에 어쩌다 저런 철부지 꼬맹이들만 남게 된 건지."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "まったく。なぜ連合に残っている者はあんな世間知らずの小童ばかりなのじゃ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Ugh. How did the Family Alliance end up with all these kids?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "傷腦筋，家族聯盟裡怎麼全都只剩下這些搞不清楚狀況的小鬼！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อึก สมาพันธ์ตระกูลมาลงเอยที่เด็กพวกนี้ได้ยังไงกันนะ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ôi. Liên Minh Gia Tộc sẽ ra sao với lũ trẻ này chứ?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "真是的，联盟怎么就只剩下这种不懂事的小孩子了。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Unglaublich. Wie kann es denn sein, dass die Familienallianz nur noch aus unreifen Gören besteht?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tss. Le Clan est tombé bien bas, pour être mené par des gamines pareilles."
L30_1.m_Talk_FRA = L31_1
