L33_1 = "SANAE_NANA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "R"
L32_1.m_Pos = L33_1
L33_1 = "지난 세월 동안 많은 일들이 있었지요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "これまで色々なことがありました。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "A lot has happened in the past years."
L32_1.m_Talk_ENG = L33_1
L33_1 = "以前曾經發生過很多事，"
L32_1.m_Talk_TWN = L33_1
L33_1 = "หลายปีนี้มีอะไรเกิดขึ้นหลายอย่างค่ะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Rất nhiều chuyện đã xảy ra trong những năm qua."
L32_1.m_Talk_VTN = L33_1
L33_1 = "以前曾经发生过很多事。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "In den letzten Jahren ist viel passiert."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Il s'en est passé des choses, pendant toutes ces années..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NANAHARA2_ACT2_INTERLUDE1@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5100201
L33_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "SANAE_NANA_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "R"
L33_1.m_Pos = L34_1
L34_1 = "신들에겐 찰나의 시간일지 모르나, 저희 같은 사람들에겐 모든 게 변하는 시간입니다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "神々には刹那に過ぎないかもしれませんが、私たちのような人間にはすべてが変わりうるほどの時間です。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "It may be a brief moment to gods, but it is enough time for everything to change for humans."
L33_1.m_Talk_ENG = L34_1
L34_1 = "對神而言或許是剎那間的時間，但我們人類而言卻是巨變。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "สำหรับเทพเจ้าแล้วอาจเป็นเพียงช่วงเวลาสั้นๆ แต่กับมนุษย์แล้วก็นานพอให้ทุกอย่างเปลี่ยนแปลงไป"
L33_1.m_Talk_THA = L34_1
L34_1 = "Với các vị thần, nó chỉ là thoáng qua, nhưng với loài ngoài, nó đủ để thay đổi mọi thứ."
L33_1.m_Talk_VTN = L34_1
L34_1 = "虽然对于神来说只是一刹那，但对于我们人类来说，却足以改变一切。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Es mag für eine Göttin wie Sie zwar nur ein kurzer Moment sein, aber für uns Menschen hat sich in dieser Zeit alles ändert."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Pour vous les dieux ce n'est peut-être qu'un bref instant mais pour nous les humains, c'est assez de temps pour tout changer."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "NANAHARA2_ACT2_INTERLUDE1@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5100201
L34_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_IDLE"
L34_1.m_Face = L35_1
L35_1 = "DRAGON_NANAHARA_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "L"
L34_1.m_Pos = L35_1
L35_1 = "녀석들의 경솔함을 감싸는 거냐? 냉철하게 판단하는 하야미 가문답지 못하구나."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "やつらの愚かな行動を庇っているのか？　冷徹に判断する速水家らしくないのう。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Are you covering for their carelessness? You are nothing like the Hayamis that I once knew."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你現在是在替他們的草率開脫嗎？一點也不像速水家族總是冷靜判斷的作風。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "นี่เจ้ากำลังกลบเกลื่อนให้ความปล่อยปละละเลยของพวกนั้นหรือไร? เจ้านี่ช่างไม่มีอะไรเหมือนฮายามิที่ข้าเคยรู้จักสักนิด"
L34_1.m_Talk_THA = L35_1
L35_1 = "Cô đang bao biện cho sự bất cẩn của họ sao? Cô chẳng giống bất kỳ người nhà Hayami nào mà tôi từng biết."
L34_1.m_Talk_VTN = L35_1
L35_1 = "你是在为她们的鲁莽行为开脱吗？这可不像是速水家族冷静判断的作风。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Versuchst du deine Nachlässigkeit zu vertuschen? Du bist ganz anders als die Hayami Familie, die ich einst kannte."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Te portes-tu garante de leur incompétence ? Toi non plus, tu n'as pas grand chose à voir avec tes aïeux."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NANAHARA2_ACT2_INTERLUDE1@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5100201
L35_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "SANAE_NANA_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "R"
L35_1.m_Pos = L36_1
L36_1 = "얼마 전, 역신이 봉인에서 풀려나는 일이 있었습니다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "少し前に、疫病神の封印が解かれる事件がございました。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Recently, the Plague God was released from her seal."
L35_1.m_Talk_ENG = L36_1
L36_1 = "瘟神不久前從封印中被釋放出來，"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เมื่อไม่นานมานี้ เทพภัยพิบัติถูกปลดปล่อยจากผนึกค่ะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Gần đây, Thần Bệnh Dịch đã được giải phong ấn."
L35_1.m_Talk_VTN = L36_1
L36_1 = "不久前，瘟疫之神从封印中被释放出来。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Vor Kurzem wurde der Gott der Verwesung von ihrem Siegel befreit."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Le Dieu du Fléau a été libéré de ses sceaux il y a peu."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA2_ACT2_INTERLUDE1@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5100201
L36_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "SANAE_NANA_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "R"
L36_1.m_Pos = L37_1
L37_1 = "당주님은 천총운검으로 목숨을 바쳐 이를 막고자 했으나, 치후유님과 연합원들의 도움으로 그 운명이 바뀌었지요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ご当主様は天叢雲剣で自らの命を捧げ、それを止めようとされました。しかし、千冬様と連合員の協力でその運命が変わったのです。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Lady Nanahara attempted to sacrifice her life to stop it with her Sword of Kusanagi. However, fate had changed thanks to the efforts of Chifuyu and the other members."
L36_1.m_Talk_ENG = L37_1
L37_1 = "堂主本想拿天叢雲劍獻上自己的性命來阻止這件事，多虧千冬和聯盟成員的幫助才改變命運。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ท่านหญิงนานะฮาระพยายามจะสังเวยตัวเองเพื่อยับยั้งมัน\nด้วยดาบคุซานางิ แต่โชคชะตาก็พลิกผันไปด้วยความพยายามของท่านชิฟุยุและสมาชิกนอื่นๆ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tiểu Thư Nanahara đã cố gắng hiến tế sinh mạng để ngăn chặn nó với Thanh Kiếm Kusanagi của cô ấy. Tuy nhiên, định mệnh đã thay đổi nhờ sự giúp đỡ của Chifuyu và những thành viên khác."
L36_1.m_Talk_VTN = L37_1
L37_1 = "家主本想献上自己的生命，用草薙剑来阻止它，但在千冬和联盟成员的帮助下，那个命运发生了改变。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Die Anführerin versuchte, ihr Leben zu opfern, um dies mit ihrem Schwert von Kusanagi zu verhindern. Dank der Bemühungen von Chifuyu und den anderen Mitgliedern hatte sich das Schicksal jedoch geändert."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Dame Nanahara a tenté de sacrifier sa vie pour l'arrêter, grâce au Kusanagi. Mais les efforts combinés de Chifuyu et les autres ont permis de changer le destin."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA2_ACT2_INTERLUDE1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5100201
L37_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_SURPRISE"
L37_1.m_Face = L38_1
L38_1 = "DRAGON_NANAHARA_NULL_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "L"
L37_1.m_Pos = L38_1
L37_1.m_Crash = 20
L38_1 = "……뭐?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "……何じゃと？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "...What?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "……什麼？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "...หา?"
L37_1.m_Talk_THA = L38_1
L38_1 = "...Cái gì?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "……什么？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "... Wie bitte?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "... Quoi ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "NANAHARA2_ACT2_INTERLUDE1@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5100201
L38_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "DRAGON_NANAHARA_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "L"
L38_1.m_Pos = L39_1
L39_1 = "그렇다면 저 작은 당주가 멀쩡히 살아서 오로치의 재림을 막았다는 거냐?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ならば、あのチビ当主は無傷でオロチの復活を止めたということか？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Then are you telling me that Ladychild stopped Orochi's resurgence and survived?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "你的意思是，那個小堂主是活生生地阻止大蛇再次來到？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เจ้าจะบอกว่าท่านหญิงน้อยนั่นยับยั้งการคืนชีพของโอโรจิแล้วยังรอดชีวิตมาได้อย่างนั้นหรือ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tức là cô đang nói với tôi rằng tiểu thư bé nhỏ đó đã ngăn chặn sự hồi sinh của Orochi mà vẫn sống sót sao?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "也就是说，小家主阻止了大蛇的再次降临，并且还活了下来？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Bedeutet das also, dass das die zierliche Anführerin überlebt und Orochis Wiederauferstehung verhindert hat?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Tu es en train de me dire que... cette mioche a empêché le retour d'Orochi... et qu'elle a survécu ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "NANAHARA2_ACT2_INTERLUDE1@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 5100201
L39_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "DRAGON_NANAHARA_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "L"
L39_1.m_Pos = L40_1
L40_1 = "오로치의 재림을 막으려면 무녀의 희생은 반드시 필요했을 텐데?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "オロチの復活を止めるためには必ず巫女の犠牲が必要なはずじゃ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Was not a sacrifice of a priestess needed in order to stop Orochi's resurgence?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "但要阻止大蛇再次來到，巫女的犧牲是不可或缺的。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "จะหยุดยั้งการฟื้นคืนของโอโรจิ นักบวชหญิงก็ต้องสังเวยตนมิใช่หรือ?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Chẳng phải sự hiến tế của một nữ tu sĩ là cần thiết để ngăn chặn Orochi hồi sinh sao?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "可是要想阻止大蛇再次降临，巫女的牺牲是不可或缺的。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "War nicht das Opfer einer Priesterin nötig, um Orochis Wiederauferstehung zu stoppen?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Mais sans le sacrifice de la prêtresse... c'est impossible !"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "NANAHARA2_ACT2_INTERLUDE1@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 5100201
L40_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "SANAE_NANA_NULL_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "R"
L40_1.m_Pos = L41_1
L41_1 = "아무런 희생이 없었던 것은 아닙니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "何の犠牲もなかったわけではございません。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I did not say there was not any sacrifice."
L40_1.m_Talk_ENG = L41_1
L41_1 = "不能說是毫無犧牲。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ข้าน้อยไม่ได้บอกว่าไม่มีการสังเวยใดๆ ค่ะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tôi không nói là không cần hiến tế."
L40_1.m_Talk_VTN = L41_1
L41_1 = "也不是没有任何牺牲。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Es ist nicht so, dass es überhaupt keine Opfer gegeben hätte."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Oh, mais... des sacrifices, il y en a eu."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "NANAHARA2_ACT2_INTERLUDE1@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5100201
L41_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "SANAE_NANA_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "R"
L41_1.m_Pos = L42_1
L42_1 = "당주님께선 천총운검의 힘을 빌어 당신의 신력을 사용하셨고, 그 대가로 바람의 목소리를 잃었습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ご当主様は天叢雲剣の力を借りてご自分の神力をお使いになり、その代償として風の声を失われました。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Lady Nanahara borrowed the powers of the Sword of Kusanagi to use her divine powers. As a result, she has lost the voice of wind."
L41_1.m_Talk_ENG = L42_1
L42_1 = "堂主借助天叢雲劍的力量使用自己的神力，然而代價就是失去風聲。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ท่านหญิงนานะฮาระยืมพลังจากดาบคุซานางิเพื่อใช้พลังลี้ลับของตน ผลคือนางสูญเสียเสียงของสายลมไป"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tiểu Thư Nanahara đã mượn sức mạnh của Thanh Kiếm Kusanagi để sử dụng sức mạnh huyền bí của mình. Vì thế mà cô ấy mất đi khả năng nghe thấy giọng nói của gió."
L41_1.m_Talk_VTN = L42_1
L42_1 = "家主借助草薙剑的力量使用了自己的神力，作为代价，风的声音不再眷顾她。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Die Anführerin hat sich die Kräfte des Schwertes von Kusanagi geliehen, um ihre göttlichen Kräfte zu nutzen. Dadurch hat sie jedoch die Stimme des Windes verloren."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Dame Nanahara a emprunté les pouvoirs de Kusanagi pour pouvoir faire appel aux pouvoirs divins. Par conséquence, elle ne peut plus entendre le chant du vent."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "NANAHARA2_ACT2_INTERLUDE1@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5100201
L42_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "DRAGON_NANAHARA_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "L"
L42_1.m_Pos = L43_1
L43_1 = "……사람을 상대로 신력을 쓴 게로군."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……人間を相手に神力を使ったのだな。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "...So she used her divine powers on another person..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "……因為把神力拿來救人吧。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "...เช่นนั้นนางจึงใช้พลังลี้ลับกับผู้อื่น..."
L42_1.m_Talk_THA = L43_1
L43_1 = "...Tức là cô ấy đã sử dụng sức mạnh huyền bí của mình cho người khác..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "……原来是把神力用来救人。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "... Also hat sie ihre göttlichen Kräfte gegen einen Menschen eingesetzt."
L42_1.m_Talk_DEU = L43_1
L43_1 = "... Je vois. Elle a utilisé les pouvoirs sur quelqu'un d'autre."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "NANAHARA2_ACT2_INTERLUDE1@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 5100201
L43_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "SANAE_NANA_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "R"
L43_1.m_Pos = L44_1
L44_1 = "당주님의 선택이 아니었다면 저와 치후유님은 살아남지 못했을 겁니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "当主様のご決断がなかったら私と千冬様は今ここにおりません。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "If it were not for Lady Nanahara's call, Miss Chifuyu and I wouldn't have survived."
L43_1.m_Talk_ENG = L44_1
L44_1 = "若非堂主的選擇，我和千冬可能早已不在人世。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "หากไม่ได้ท่านหญิงนานะฮาระ ข้าน้อยกับท่านชิฟุยุก็คงไม่อาจรอดชีวิตมาได้ค่ะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nếu Tiểu Thư Nanahara không quyết định như thế, tôi và cả Cô Chifuyu đã không sống sót nổi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "若非家主的选择，我和千冬可能早已不在人世。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ohne die Wahl der Anführerin hätten Chifuyu und ich nicht überlebt."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Sans elle, Chifuyu et moi-même n'aurions pas survécu."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "NANAHARA2_ACT2_INTERLUDE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 5100201
L44_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "SANAE_NANA_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "R"
L44_1.m_Pos = L45_1
L45_1 = "그랬다면…… 나오님께서 찾으시는 나나하라에 무사는 한 사람도 남지 않았겠지요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "そうなれば……ナオ様がお探しの七原に武士は一人も残っていなかったでしょう。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "If that had happened... there will be no warrior in the Nanahara family whom you are looking for."
L44_1.m_Talk_ENG = L45_1
L45_1 = "那麼……您找上的七原中也就不再有任何武士存在。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "และหากเป็นเช่นนั้น... ก็คงไม่มีนักรบในตระกูลนานะฮาระที่ท่านตามหาอยู่"
L44_1.m_Talk_THA = L45_1
L45_1 = "Nếu điều đó xảy ra... Cô sẽ chẳng tìm nổi một chiến binh nào trong gia tộc Nanahara nữa."
L44_1.m_Talk_VTN = L45_1
L45_1 = "那样的话……奈绪大人寻找的七原武士就一个都不剩了。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Wenn das passiert wäre ... gäbe es in der Familie Nanahara keinen Krieger mehr, nach dem Sie suchen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Si tel avait été le cas... le guerrier Nanahara que vous essayez d'éveiller n'existerait pas."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "NANAHARA2_ACT2_INTERLUDE1@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 5100201
L45_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "UNIT_DESPAIR"
L45_1.m_Face = L46_1
L46_1 = "DRAGON_NANAHARA_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "L"
L45_1.m_Pos = L46_1
L46_1 = "그래서……?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "で……？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "So...?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "所以呢……？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แล้วอย่างไรเล่า...?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Vậy...?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "所以呢……？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Also ...?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Et donc...?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "NANAHARA2_ACT2_INTERLUDE1@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5100201
L46_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "DRAGON_NANAHARA_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "L"
L46_1.m_Pos = L47_1
L47_1 = "나더러 당주 녀석을 칭찬이라도 해달라는 거냐?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "わしに当主を褒めろとでもいうのか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Are you implying that I should praise her?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "你現在是要我誇獎那個小堂主好棒嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "จะบอกว่าข้าควรชื่นชมนางเช่นนั้นหรือ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ý cô là tôi nên khen ngợi cô ấy sao?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "你是想让我夸奖她吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Willst du, dass ich die Anführerin dafür lobe?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Essaies-tu de me dire que je dois lui être reconnaissance ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "NANAHARA2_ACT2_INTERLUDE1@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 5100201
L47_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "UNIT_SERIOUS"
L47_1.m_Face = L48_1
L48_1 = "DRAGON_NANAHARA_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "L"
L47_1.m_Pos = L48_1
L48_1 = "작은 당주가 생명의 기적을 대가로 바람의 목소리를 잃었다는 건, 가문연합이 다음 운명을 미리 알고 대비할 수 없다는 뜻이다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "チビ当主が命の奇跡の代償として風の声を失ったということは、連合が次の運命をあらかじめ知り、備えることができないということじゃ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "The fact that this Ladychild performed a miracle at the cost of losing the voice of wind means that the Family Alliance has no way of foreseeing fate and preparing for it."
L47_1.m_Talk_ENG = L48_1
L48_1 = "小堂主失去風聲，也就表示家族聯盟將無法再防患未然。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "การที่ท่านหญิงน้อยสร้างปาฏิหาริย์โดยแลกกับการเสียเสียงของสายลมไป ก็หมายความว่าสมาพันธ์ตระกูลสิ้นไร้หนทางจะเห็นโชคชะตาล่วงหน้าและเตรียมรับมือกับมันไปแล้ว"
L47_1.m_Talk_THA = L48_1
L48_1 = "Việc Tiểu Thư thực hiện phép màu đã bị đánh đổi bằng khả năng nghe thấy giọng nói của gió, nghĩa là Liên Minh Gia Tộc không còn khả năng nhìn thấy trước định mệnh và chuẩn bị cho nó nữa."
L47_1.m_Talk_VTN = L48_1
L48_1 = "小家主以失去风的声音为代价获得了生命的奇迹，这意味着联盟不再能够预知并应对未来的命运。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Die Tatsache, dass die zierliche Anführerin ein Wunder vollbracht und dabei die Stimme des Windes verloren hat, bedeutet, dass die Familienallianz keine Möglichkeit hat, das Schicksal vorherzusehen und sich darauf vorzubereiten."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Cette petite inconsciente a perdu le chant du vent pour sauver quelques vies. Et à cause de ça, le Clan ne pourra plus jamais prévoir les catastrophes à venir."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "NANAHARA2_ACT2_INTERLUDE1@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5100201
L48_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "DRAGON_NANAHARA_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "L"
L48_1.m_Pos = L49_1
L49_1 = "바로 지금, 배반자 놈 하나 때문에 우리가 궁지에 몰린 것처럼 말이지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ちょうど今も、裏切り者一人のせいでわしらが窮地に追い込まれているではないか。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Just like how we are cornered because of one traitor."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我們現在才會因為一個叛徒就被逼到絕境。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ดังเช่นที่เราจนมุมเพราะคนทรยศเพียงคนเดียว"
L48_1.m_Talk_THA = L49_1
L49_1 = "Giống như khi chúng ta bị dồn vào đường cùng vì một tên phản bội."
L48_1.m_Talk_VTN = L49_1
L49_1 = "就像此时此刻，我们因为一个叛徒被逼入绝境一样。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Genauso wie wir gerade wegen eines Verräters in die Enge getrieben werden."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ni celles en cours, d'ailleurs. Comme en témoigne la facilité avec laquelle ce traître est en train de nous balader."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "NANAHARA2_ACT2_INTERLUDE1@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
