L2_1 = "NANAHARA2_ACT2_INTERLUDE1@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 5100201
L1_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "SANAE_NANA_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "하지만 소인은 주어진 운명보다……"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ですが、私は与えられた運命より……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "However, I want to put my trust in the heart of people..."
L1_1.m_Talk_ENG = L2_1
L2_1 = "但我不想相信既定的命運……"
L1_1.m_Talk_TWN = L2_1
L2_1 = "กระนั้น ข้าน้อยก็ยังเชื่อมั่นใจหัวใจของผู้คน..."
L1_1.m_Talk_THA = L2_1
L2_1 = "Tuy nhiên, tôi muốn đặt niềm tin của mình vào trái tim của mọi người..."
L1_1.m_Talk_VTN = L2_1
L2_1 = "但是比起给定的命运……"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Aber anstatt dem vorherbestimmten Schicksal zu vertrauen ..."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Cependant, plutôt que de m'en remettre à un destin inéluctable..."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NANAHARA2_ACT2_INTERLUDE1@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5100201
L2_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "SANAE_NANA_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "서로를 지키고자 하는 사람의 마음을 믿고 싶습니다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "お互いを守ろうとする人の心を信じたいのです。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Rather than in a predetermined fate."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我想相信人們彼此守護的心。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "มากกว่าโชคชะตาที่กำหนดไว้แล้วนะคะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Hơn là định mệnh được định sẵn."
L2_1.m_Talk_VTN = L3_1
L3_1 = "我更想相信人们想要保护彼此的心意。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Möchte ich lieber an die Herzen der Menschen glauben, die sich gegenseitig beschützen wollen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Je préfère accorder ma confiance au cœur de certaines personnes."
L2_1.m_Talk_FRA = L3_1
