L6_1 = "NANAHARA2_ACT2_INTERLUDE1@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5100201
L5_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "여기에 계십시오, 전대장님. 놈들을 막는 건 저희에게 맡겨 주시면 됩니다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ここにいてください、戦隊長。やつらを止めるのは私たちにお任せください。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Please stay here, Commander. Leave it to us to block them."
L5_1.m_Talk_ENG = L6_1
L6_1 = "請戰隊長待在這裡，其他人就交給我們處理。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "โปรดอยู่ที่นี่เถอะครับผู้บัญชาการ พวกเราจะสกัดกั้นพวกมันเอง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Xin cứ ở lại đây, Tổng Tư Lệnh. Hãy để chúng tôi chặn chúng."
L5_1.m_Talk_VTN = L6_1
L6_1 = "请留在这里，战队长。那些家伙，就交给我们来阻止吧。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Bleiben Sie bitte hier, Kommandantin. Überlassen Sie es uns, diese Kerle aufzuhalten."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Restez ici, commandante. Nous allons nous occuper d'eux."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "NANAHARA2_ACT2_INTERLUDE1@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 5100201
L6_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "무슨 일이 있어도, 절대로 밖으로 나오지 마세요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "何があっても、絶対に外に出ないでください。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Whatever happens, never step outside."
L6_1.m_Talk_ENG = L7_1
L7_1 = "無論發生什麼事都絕對不要出來。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ไม่ว่าจะเกิดอะไรขึ้น อย่าออกไปนะครับ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Dù chuyện gì xảy ra, đừng bao giờ bước ra ngoài."
L6_1.m_Talk_VTN = L7_1
L7_1 = "不管发生什么事，您都绝对不要出来。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Was auch immer passiert, kommen Sie nicht raus."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Surtout, ne quittez cet endroit sous aucun prétexte."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "NANAHARA2_ACT2_INTERLUDE1@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 5100201
L7_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "이번엔 저희가 대장님을 구해드릴 테니까요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "今度は私たちが隊長を助けますから。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "It's our turn to save you."
L7_1.m_Talk_ENG = L8_1
L8_1 = "這次換我們救戰隊長。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ถึงคราวที่พวกเราต้องช่วยท่านบ้างแล้ว"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đến lượt chúng tôi cứu cô."
L7_1.m_Talk_VTN = L8_1
L8_1 = "这次换我们来救队长了。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Dieses Mal werden wir Sie retten, Kommandantin."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Cette fois-ci, c'est à notre tour de vous sauver."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
