L10_1 = "NANAHARA2_ACT2_INTERLUDE1@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5100201
L9_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "DRAGON_NANAHARA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "하아…… 가문연합도 예전 같질 않구만."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "はあ……連合も変わったのう。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "*Sigh...* The Family Alliance is not what it was before."
L9_1.m_Talk_ENG = L10_1
L10_1 = "哀……家族聯盟也早就人事已非，"
L9_1.m_Talk_TWN = L10_1
L10_1 = "*เฮ้อ...* สมาพันธ์ตระกูลไม่เหมือนเดิมแล้วสินะ"
L9_1.m_Talk_THA = L10_1
L10_1 = "*Thở dài...* Liên Minh Gia Tộc không còn như trước nữa."
L9_1.m_Talk_VTN = L10_1
L10_1 = "哈啊……联盟早就已经物是人非了。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "*Seufz* Die Familienallianz ist nicht mehr das, was sie einmal war."
L9_1.m_Talk_DEU = L10_1
L10_1 = "*Soupir* Le Clan n'est vraiment plus ce qu'il était."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NANAHARA2_ACT2_INTERLUDE1@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 5100201
L10_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "DRAGON_NANAHARA_NULL_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "이놈이나 저놈이나 꿈같은 소릴 지껄이고 말이야."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "どいつもこいつも夢のような話ばかり言う。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Everyone here seems to be daydreaming."
L10_1.m_Talk_ENG = L11_1
L11_1 = "每一個人都在痴人說夢話。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ทุกคนที่นี่ดูจะเอาแต่ฝันลมๆ แล้งๆ กันไปหมด"
L10_1.m_Talk_THA = L11_1
L11_1 = "Mọi người ở đây dường như đang mơ giữa ban ngày."
L10_1.m_Talk_VTN = L11_1
L11_1 = "一个个的全都在说梦话呢。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Jeder hier scheint vor sich hin zu träumen."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Il n'y en a pas un pour rattraper l'autre... vous n'êtes qu'une brochette de rêveurs, d'idéalistes."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
