L13_1 = "NANAHARA2_ACT2_INTERLUDE1@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5100201
L12_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "UNIT_DESPAIR"
L12_1.m_Face = L13_1
L13_1 = "DRAGON_NANAHARA_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "넌…… 내가 원망스럽지 않으냐?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "お主は……わしを恨んではおらんのか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "You... Do you resent me?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "你……不恨我嗎？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "เจ้า... ขัดเคืองข้ารึ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Cô...Cô tức giận với tôi sao?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "你……不怨我吗？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Du ... Bist du nicht böse auf mich?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Dis-moi... n'éprouves-tu donc aucune rancœur à mon égard ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "NANAHARA2_ACT2_INTERLUDE1@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5100201
L13_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "DRAGON_NANAHARA_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "살아있으면서 여태 낯짝 한 번 안 비추던 자가 이제서야 나타났는데 말이지."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "生きているにもかかわらず、今まで顔を出したこともない者が今更のこのこやって来たんだぞ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I have been alive for all these years, and yet, I decided to show up now."
L13_1.m_Talk_ENG = L14_1
L14_1 = "明明還活著，卻從未露過面，一直到現在才出現。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ข้ามีชีวิตอยู่มาไม่รู้กี่ปีต่อกี่ปี จนตัดสินใจมาปรากฏตัวเอาป่านนี้"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi đã sống ngần ấy năm, vậy mà, lúc này tôi lại quyết định xuất hiện."
L13_1.m_Talk_VTN = L14_1
L14_1 = "明明还活着，却从未露面，一直到如今才出现。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich war all die Jahre am Leben und habe mich dennoch entschieden, jetzt erst aufzutauchen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "J'ai traversé les âges, et pourtant... j'ai décidé de me montrer seulement maintenant."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "NANAHARA2_ACT2_INTERLUDE1@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5100201
L14_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "UNIT_IDLE"
L14_1.m_Face = L15_1
L15_1 = "SANAE_NANA_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "모든 일이 뜻대로 순탄하게 흘러가지만은 않는 법이지요."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "すべてが思いどおり順調にいくことなどありえません。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Not everything can be as we plan them to be."
L14_1.m_Talk_ENG = L15_1
L15_1 = "並非所有事情都能如我們所願，"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ไม่ใช่ว่าทุกอย่างจะเป็นไปได้ดังที่เราวางแผนไว้หรอกค่ะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Không phải mọi thứ đều có thể như chúng ta dự tính."
L14_1.m_Talk_VTN = L15_1
L15_1 = "不是所有事都会尽如人意。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Nicht alles läuft so reibungslos, wie wir es uns wünschen."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Les choses ne se déroulent pas toujours comme nous le souhaitons. Ainsi va la vie."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "NANAHARA2_ACT2_INTERLUDE1@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5100201
L15_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "SANAE_NANA_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "나오님께서도 그럴 수밖에 없는 사정이 있었을 거라 생각합니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ナオ様にもそうするしかない事情がおありだったのでしょう。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I'm sure you had your reasons to do so, Miss Nao."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我相信您也是逼不得已的。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ข้าน้อยมั่นใจว่าท่านเองก็มีเหตุผลที่ทำเช่นนั้น ท่านนาโอะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi chắc rằng cô có lý do để làm như vậy, cô Nao."
L15_1.m_Talk_VTN = L16_1
L16_1 = "我相信奈绪大人也有无可奈何的理由。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich bin mir sicher, Sie hatten Ihre Gründe dafür, so zu handeln, Fräulein Nao."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Je suis sûre que vous avez vos raisons, madame Nao."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NANAHARA2_ACT2_INTERLUDE1@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
