L18_1 = "NANAHARA2_ACT2_INTERLUDE1@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5100201
L17_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "DRAGON_NANAHARA_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "그렇게 말해도, 지금의 당주가 불안한 건 변함없는 사실이다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "そうは言っても、今の当主が不安であることには変わりない。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Even if you say that, it does not change the fact that the current leader of Nanahara is unstable."
L17_1.m_Talk_ENG = L18_1
L18_1 = "就算你這麼說，現在的堂主令人擔憂還是事實。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ต่อให้เจ้ากล่าวเช่นนั้น ก็ไม่ได้เปลี่ยนความจริงที่ว่าผู้นำนานะฮาระคนปัจจุบันเอาแน่เอานอนไม่ได้หรอก"
L17_1.m_Talk_THA = L18_1
L18_1 = "Ngay cả khi nói vậy, điều đó cũng không thay đổi được sự thật rằng thủ lĩnh hiện tại của Nanahara không ổn định."
L17_1.m_Talk_VTN = L18_1
L18_1 = "就算你这样说，现在家主的情况还是令人担忧。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Selbst wenn du das so sagst, ändert es nichts an der Tatsache, dass die derzeitige Anführerin instabil ist."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Quoi que tu dises, l'actuelle dirigeante du Clan Nanahara est instable. C'est un fait."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
