L21_1 = "NANAHARA2_ACT2_INTERLUDE1@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5100201
L20_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "UNIT_IDLE"
L20_1.m_Face = L21_1
L21_1 = "DRAGON_NANAHARA_NULL_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "L"
L20_1.m_Pos = L21_1
L21_1 = "지금의 선택을 후회하지나 말거라. 날개 부러진 새에게 다음 기적은 없을 테니."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "今の選択を後悔するでないぞ。翼が折れた鳥にもう奇跡は起こらん。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Do not regret the choices you made. A wingless bird will never get another chance to fly."
L20_1.m_Talk_ENG = L21_1
L21_1 = "不要對現在的選擇後悔，折翼的鳥是不會再有下一個奇蹟的。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "อะไรที่เลือกไปแล้วก็อย่าได้เสียใจ นกไร้ปีกน่ะไม่มีโอกาสได้บินอีกหรอกนะ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Cô không cần hối hận vì những lựa chọn của mình. Một chú chim không có cánh không có cơ hội nào khác để bay lên trời."
L20_1.m_Talk_VTN = L21_1
L21_1 = "别后悔现在的选择。折断了翅膀的鸟是不会再有下一个奇迹的。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Bereue nicht die Entscheidungen, die du getroffen hast. Ein Vogel mit gebrochenem Flügel wird nämlich nie wieder eine Chance zum Fliegen bekommen."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Enfin, trop tard pour les regrets. Un oiseau sans ailes ne pourra plus jamais voler."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "NANAHARA2_ACT2_INTERLUDE1@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5100201
L21_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "UNIT_IDLE"
L21_1.m_Face = L22_1
L22_1 = "SANAE_NANA_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "R"
L21_1.m_Pos = L22_1
L22_1 = "……낭떠러지인 줄 알면서도 기적을 바라고 뛰어들진 않습니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "……崖であることを知りながら、奇跡を願って飛び込んだりはしません。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I do not pray for a miracle whilst knowing that the edge of a cliff is nearing."
L21_1.m_Talk_ENG = L22_1
L22_1 = "……我不會對著懸崖縱身而下期待有奇蹟出現，"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ยามรู้ว่าตนจวนเจียนจะตกหน้าผา ข้าน้อยก็มิได้เอาแต่ภาวนาให้เกิดปาฏิหาริย์หรอกนะคะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi không cầu xin một phép màu khi biết rằng vực thẳm đang ở gần kề."
L21_1.m_Talk_VTN = L22_1
L22_1 = "……我不会因为期待奇迹出现而对着悬崖纵身而下。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "... Ich hoffe nicht auf ein Wunder, obwohl ich weiß, dass wir auf den Rand einer Klippe zusteuern."
L21_1.m_Talk_DEU = L22_1
L22_1 = "... Je ne vais pas me jeter du précipice en espérant un miracle."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NANAHARA2_ACT2_INTERLUDE1@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5100201
L22_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_LAUGH"
L22_1.m_Face = L23_1
L23_1 = "SANAE_NANA_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "R"
L22_1.m_Pos = L23_1
L23_1 = "하지만 적어도 날갯짓은 해봐야겠지요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "でも、少なくとも飛ぼうとはしてみなければ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "However, I will at least try to flap my wings."
L22_1.m_Talk_ENG = L23_1
L23_1 = "但至少可以嘗試看看振翅飛翔。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แต่อย่างน้อย ข้าน้อยก็จะพยายามกระพือปีกค่ะ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tuy nhiên, ít nhất tôi vẫn sẽ cố gắng vỗ cánh."
L22_1.m_Talk_VTN = L23_1
L23_1 = "但至少我会尽力挥动翅膀。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Allerdings werde ich zumindest versuchen, mit den Flügeln zu schlagen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Mais jusqu'au bout, j'essaierai de déployer mes ailes."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
