L28_1 = "NANAHARA2_ACT2_INTERLUDE1@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5100201
L27_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "CHIFUYU_NANA_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "이곳에서 하야미 공과 마지막으로 수련을 한 지도 꽤 많은 시간이 흘렀구나."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ここで速水殿と最後に修練をしてからずいぶんと経ったものだな。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "A long time has passed since my last training with Dame Sanae here."
L27_1.m_Talk_ENG = L28_1
L28_1 = "上次和速水在這裡練習也已經是好久以前的事呢。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ตั้งแต่ครั้งสุดท้ายที่ฝึกกับนายท่านฮายามิ เวลาก็ผ่านมานานแล้ว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Đã lâu lắm rồi kể từ lần cuối cùng mình luyện tập với Lãnh Chúa Hayami ở đây."
L27_1.m_Talk_VTN = L28_1
L28_1 = "在这里和速水进行最后的修炼，也是过去很久的事了啊。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Es ist ziemlich viel Zeit vergangen, seit ich hier das letzte Mal mit Sanae trainiert habe."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Cela me rappelle ma formation avec Dame Sanae. C'était il y a si longtemps..."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
