L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5100201
L30_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "UNIT_IDLE"
L30_1.m_Face = L31_1
L31_1 = "SANAE_NANA_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "어떤 느낌이 드시는지요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "どんな感じがしますか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "How do you feel?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "您有什麼感覺？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เป็นเช่นไรคะ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cô cảm thấy sao?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "您有什么感觉？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wie fühlen Sie sich?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Comment vous sentez-vous ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5100201
L31_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = false
L31_1.m_fWaitTime = 0
L32_1 = "SANAE_NANA_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C_D"
L32_1 = {}
L33_1 = "NANAHARA2_ACT2_INTERLUDE1@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5100201
L32_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "CHIFUYU_NANA_NULL_YOUNG"
L32_1.m_CharStrID = L33_1
L33_1 = "이 동굴은 서늘하고…… 어두워서 아무것도 보이지 않습니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "この洞窟は涼しく……暗くて何も見えません。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "The cave is too cold... and too dark to see anything."
L32_1.m_Talk_ENG = L33_1
L33_1 = "這個洞穴又冷……又黑，我什麼都看不到。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ถ้ำหนาวมาก... แล้วก็มืดจนมองอะไรไม่เห็นเลยค่ะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Hang này lạnh quá...và tối tăm đến mức chẳng nhìn thấy gì.."
L32_1.m_Talk_VTN = L33_1
L33_1 = "这个洞窟阴冷……黑暗，什么也看不见。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Die Höhle ist zu kalt ... und zu dunkel, um etwas sehen zu können."
L32_1.m_Talk_DEU = L33_1
L33_1 = "La grotte est trop froide, trop sombre pour y voir quoi que ce soit."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NANAHARA2_ACT2_INTERLUDE1@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5100201
L33_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "SANAE_NANA_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "그렇다면 벽을 한 번 손으로 짚어 보시지요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "でしたら、一度壁を触ってみてください。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Then try placing your hand on the wall."
L33_1.m_Talk_ENG = L34_1
L34_1 = "您用手摸摸看牆壁。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เช่นนั้นก็ลองเอามือคลำไปตามผนังเอานะคะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vậy hãy thử đặt tay lên tường xem."
L33_1.m_Talk_VTN = L34_1
L34_1 = "那你用手摸摸墙。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Dann versuchen Sie mal mit Ihrer Hand die Wand zu berühren."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Dans ce cas, repérez-vous en touchant les murs autour de vous."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
