L35_1 = {}
L36_1 = "NANAHARA2_ACT2_INTERLUDE1@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5100201
L35_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "CHIFUYU_NANA_NULL_YOUNG"
L35_1.m_CharStrID = L36_1
L36_1 = "이건……? 마치 짐승의 발톱이 무수히 할퀴고 지나간 듯한……"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "これは……？　まるで獣が爪で何度もひっかいたような……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Hmm...? It's as if a beast ran its claws through it..."
L35_1.m_Talk_ENG = L36_1
L36_1 = "這是……？好像被野獸抓過的痕跡……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "หือ...? อย่างกับเคยมีสัตว์ร้ายมาฝากรอยเล็บไว้เลย"
L35_1.m_Talk_THA = L36_1
L36_1 = "Hmm...? Như thể một con thú cào móng vuốt lên nó..."
L35_1.m_Talk_VTN = L36_1
L36_1 = "这是……？好像被野兽的爪子抓过无数次一样……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Hmm ...? Es fühlt sich so an, als ob ein Tier mit seinen Krallen an der Wand gekratzt hätte ..."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Hmm... ? Cette forme... on dirait qu'une gigantesque bête a griffé la roche."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA2_ACT2_INTERLUDE1@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5100201
L36_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "CHIFUYU_NANA_NULL_YOUNG"
L36_1.m_CharStrID = L37_1
L37_1 = "……아니, 아주 예리한 검의 날끝이 베고 지나간 흔적이군요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "……いや、とても鋭い刃先でつけられた跡ですね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "...No. These are markings of a sharp blade."
L36_1.m_Talk_ENG = L37_1
L37_1 = "……不對，應該非常銳利的刀鋒劃過的痕跡。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "...มิได้ค่ะ นี่คือรอยคมดาบ"
L36_1.m_Talk_THA = L37_1
L37_1 = "...Không. Nó là dấu vết của một thanh kiếm sắc bén."
L36_1.m_Talk_VTN = L37_1
L37_1 = "……啊不对，这是非常锋利的剑锋砍过的痕迹。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "... Nein, es sind die Spuren einer sehr scharfen Klinge."
L36_1.m_Talk_DEU = L37_1
L37_1 = "... Non. Ces traces, elles ont été laissées par une lame."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA2_ACT2_INTERLUDE1@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5100201
L37_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "UNIT_SERIOUS"
L37_1.m_Face = L38_1
L38_1 = "SANAE_NANA_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "이곳은 오래 전, 명부신께서 검술을 연마하셨던 장소입니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ここは昔、冥府の神が剣術を鍛錬なさった場所です。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "This is where the Nether God used to practice his swordsmanship a long time ago."
L37_1.m_Talk_ENG = L38_1
L38_1 = "這裡很久以前是冥府神練劍的地方。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "นี่คือที่ที่ยมราชเคยใช้ฝึกวิชาดาบเมื่อนานมาแล้วค่ะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đây là nơi Thần Âm Ty đã dùng để luyện kiếm rất lâu trước đây."
L37_1.m_Talk_VTN = L38_1
L38_1 = "这里是很久以前，冥神练习剑法的地方。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Dies ist der Ort, an dem der Gott des Jenseits vor langer Zeit seine Schwertkunst ausübte."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Jadis, c'est ici que le Dieu du Néant venait s'entraîner à l'épée."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "NANAHARA2_ACT2_INTERLUDE1@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5100201
L38_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "SANAE_NANA_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "처음에는 작은 바위산이었으나, 수천년에 걸쳐 검술을 연마한 끝에 이런 깊은 동굴이 만들어졌다고 하지요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "最初は小さな岩山でしたが、数千年にわたる剣術の鍛錬により、ついにはこのような深い洞窟になったと伝えられています。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "It used to be a small mountain. But after thousands of years of slashing, a deep cave was formed."
L38_1.m_Talk_ENG = L39_1
L39_1 = "原本是個小小的石頭山，經過數千年在此練劍後，最後變成一個很深的洞穴。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ที่นี่เคยเป็นภูเขาลูกเล็กๆ แต่เมื่อถูกฟาดฟันหลายพันปีเข้า ก็เกิดเป็นถ้ำลึกขึ้นมา"
L38_1.m_Talk_THA = L39_1
L39_1 = "Vốn nó là một ngọn núi nhỏ. Nhưng sau hàng ngàn năm bị rạch chém, nó đã trở thành một hang động sau."
L38_1.m_Talk_VTN = L39_1
L39_1 = "最初是一座小小的石山，经过数千年在此练剑后，这里变成一个很深的洞窟。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Zuerst war es nur ein kleiner felsiger Berg, aber nach Tausenden von Jahren der Verfeinerung der Schwertkunst soll diese tiefe Höhle entstanden sein."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Au départ, il n'y avait qu'une formation rocheuse. Un gros caillou. Mais après plusieurs milliers d'années à le taillader tous les jours... une cavité a fini par se former."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
