L41_1 = "NANAHARA2_ACT2_INTERLUDE1@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 5100201
L40_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "CHIFUYU_NANA_NULL_YOUNG"
L40_1.m_CharStrID = L41_1
L41_1 = "신이 이런 곳에서 수련을 했다니…… 무척 신기합니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "神がこんなところで修練を……とても不思議です。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "It's astonishing to learn that a god once trained in a place like this..."
L40_1.m_Talk_ENG = L41_1
L41_1 = "神竟然曾經在這種地方練劍……好神奇喔。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "การได้รู้ว่าครั้งหนึ่งเทพเจ้าเคยมาฝึกฝนในที่แบบนี้นี่น่าตกใจมากนะคะ..."
L40_1.m_Talk_THA = L41_1
L41_1 = "Thật đáng kinh ngạc khi một vị thần từng luyện tập ở một nơi như thế này..."
L40_1.m_Talk_VTN = L41_1
L41_1 = "神居然在这种地方修炼……好神奇。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Es ist erstaunlich, dass ein Gott einst an einem Ort wie diesem trainiert hat ..."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Le terrain d'entraînement d'un dieu... c'est fascinant."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "NANAHARA2_ACT2_INTERLUDE1@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5100201
L41_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "CHIFUYU_NANA_NULL_YOUNG"
L41_1.m_CharStrID = L42_1
L42_1 = "그럼 이 벽에 새겨진 검자국들이 명부신의 검술인 건가요?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "それでは、この壁に残された刀傷が冥府の神の剣術なのですか？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "So all these markings on the wall are traces of the Nether God's sword skills?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "那刻在牆壁上的劍痕就是冥府神的劍法嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "งั้นทั้งหมดบนกำแพงนี่ก็คือร่องรอยวิชาดาบของยมราชเหรอคะ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Vậy là tất cả những dấu vết trên tường đều là minh chứng về kỹ năng dùng kiếm của Thần Âm Ty sao?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "那这墙壁上刻着的剑痕是冥神的剑法吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Sind die in diese Wand eingravierten Schwertspuren also die Schwertkunst des Gottes des Jenseits?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Alors toutes ces traces sur le mur... ce sont les marques laissées par ses coups d'épée ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "NANAHARA2_ACT2_INTERLUDE1@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5100201
L42_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_IDLE"
L42_1.m_Face = L43_1
L43_1 = "SANAE_NANA_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "그렇습니다. 이 동굴에 새겨진 명부신의 검술을 해석하여 풀이한 것이 나나하라류의 원류."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "そのとおりです。この洞窟に刻まれた冥府の神の剣術を解釈して説いたのが七原流の源流。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Correct. The origin of the Nanahara style was made by interpreting the engraved markings of this cave made by the Nether God."
L42_1.m_Talk_ENG = L43_1
L43_1 = "沒錯，將刻在洞穴中的冥府神劍法分析解釋後，於是形成最初的七原流。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ใช่แล้วค่ะ ต้นกำเนิดของวิชาต่อสู้สายนานะฮาระ ก็มาจากการตีความรอบฟาดฟันของยมราชที่ทำให้เกิดถ้ำนี้ค่ะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Chính xác. Trường Phái Nanahara chính là kiến giải từ những vết tích được khắc trong hang động này của Thần Âm Ty."
L42_1.m_Talk_VTN = L43_1
L43_1 = "是的。分析、拆解这个洞窟里刻着的冥神剑法是七原流的初衷。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "So ist es. Der Ursprung des Nanahara-Stils ist die in dieser Höhle eingravierte Interpretation der Schwertkunst des Gottes des Jenseits."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Correct. C'est d'ailleurs l'étude de ces traces qui constitue les fondements du style Nanahara."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "NANAHARA2_ACT2_INTERLUDE1@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 5100201
L43_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "SANAE_NANA_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "저희 가문에서 명검이라 불리는 이들은 모두 이 동굴에서 수행했지요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "速水家で名を馳せた者たちはみなこの洞窟で修行いたしました。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Even the greatest sword masters in my family have all trained inside this cave."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我們家族中稱為名劍的人，都曾在這個洞穴裡修行過。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "กระทั่งนักดาบที่มากทักษะที่สุดในตระกูลข้าน้อย ก็ยังต้องมาฝึกในถ้ำนี้ค่ะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ngay cả những kiếm sư hàng đầu trong gia đình tôi cũng luyện tập trong hang này."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我们家族里被称为名剑的人，全都在这个洞窟里修行过。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Alle berühmten Schwertkämpfer meiner Familie haben in dieser Höhle trainiert."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Les plus grands maîtres épéistes de ma famille se sont tous entraînés à l'intérieur de cette grotte."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "NANAHARA2_ACT2_INTERLUDE1@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 5100201
L44_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "SANAE_NANA_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "그러나 수많은 인재들이 거쳐갔음에도, 그것을 완벽히 이해한 자는 한 명도 없었습니다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ですが、数多くの才能ある者たちがここで修練しましたが、冥府の神の剣術を完璧に理解できた者はおりませんでした。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "But even though many talented individuals have come and gone, no one has been able to fully understand it."
L44_1.m_Talk_ENG = L45_1
L45_1 = "然而即使有那麼多的人才曾來這裡取經，卻沒有一個人能夠完全理解冥府神的劍法。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แต่แม้จะมีผู้มีความสามารถหลายคนมาที่นี่แล้วจากไป แต่ก็ยังไม่มีใครสามารถเข้าใจอย่างถ่องแท้เลย"
L44_1.m_Talk_THA = L45_1
L45_1 = "Nhưng dù có nhiều thiên tài đã đến và đi, vẫn chưa ai có thể hiểu hết ý nghĩa của chúng."
L44_1.m_Talk_VTN = L45_1
L45_1 = "但即使如此，也没有一个人能彻底参悟它。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Aber obwohl viele talentierte Menschen diesen Ort besuchten, konnte niemand die Eingravierung vollständig verstehen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Mais malgré tous les épéistes de talent qui se sont succédés au fil des siècles... personne n'est jamais parvenu à appréhender complètement ces marques."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 5100201
L45_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L45_1.m_bWaitClick = false
