L47_1 = "NANAHARA2_ACT2_INTERLUDE1@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5100201
L46_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "CHIFUYU_NANA_NULL_YOUNG"
L46_1.m_CharStrID = L47_1
L47_1 = "제가 이런 곳에 들어올 자격이 되는 걸까요?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "私などがここに入る資格があるのでしょうか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Do you think I am qualified to even be here?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "我有資格進來這裡嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ท่านคิดว่าข้ามีคุณสมบัติจะมาที่นี่เหรอคะ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cô có nghĩ tôi đủ tư cách ở đây không?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "我有资格进这种地方吗？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Habe ich es überhaupt verdient, an diesem Ort zu sein?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Pensez-vous que je suis qualifiée pour être ici ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "NANAHARA2_ACT2_INTERLUDE1@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 5100201
L47_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "UNIT_LAUGH"
L47_1.m_Face = L48_1
L48_1 = "SANAE_NANA_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "치후유님께선 이미 제가 가르칠 수 있는 나나하라류의 모든 것을 받아들이셨습니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "千冬様にはすでに私に教えられる七原流のすべてをお教えしました。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You have already surpassed all that I can teach you about the Nanahara style, Miss Chifuyu."
L47_1.m_Talk_ENG = L48_1
L48_1 = "我已經將我畢生所學的七原流都傳授給您，而您也已經學會。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ท่านเหนือกว่าทุกสิ่งเกี่ยวกับวิชาต่อสู้สายนานะฮาระที่ข้าน้อยสอนให้แล้วนะคะ ท่านชิฟุยุ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Cô đã thành thạo mọi điều mà tôi có thể dạy cô về Trường Phái Nanahara rồi, Cô Chifuyu."
L47_1.m_Talk_VTN = L48_1
L48_1 = "我已经将毕生所学都教授给了您，就现在我所知道的七原流来说，您已经掌握了全部。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Sie haben bereits alles akzeptiert, was ich Ihnen über den Nanahara-Stil beibringen kann, Fräulein Chifuyu."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous avez déjà appris tout ce que j'avais à vous enseigner sur les arcanes du style Nanahara, Chifuyu."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "NANAHARA2_ACT2_INTERLUDE1@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5100201
L48_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "SANAE_NANA_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "더 나아가 극의를 깨우치고 싶으시다면, 이 방법이 유일한 길이겠지요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "さらに極意を悟りたければ、これが唯一の方法となるでしょう。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "If you want ultimate realization, this is the only way."
L48_1.m_Talk_ENG = L49_1
L49_1 = "若想再邁向更高境界，這是唯一的辦法。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "หากท่านต้องการจะรู้ให้แจ่มแจ้ง ก็มีเพียงทางนี้เท่านั้น"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nếu cô muốn có được sự công nhận cuối cùng, đây là cách duy nhất."
L48_1.m_Talk_VTN = L49_1
L49_1 = "如果还想进一步领悟剑中的极意，这是唯一的办法。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wenn Sie sich die ultimative Erkenntnis wünschen, ist dies der einzige Weg, um sie zu erlangen."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Si vous voulez atteindre la transcendance, c'est le seul chemin possible."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
