L2_1 = "NANAHARA2_ACT2_INTERLUDE1@201#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 201
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 5100201
L1_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "그 뒤로 한동안 동굴에 새겨진 칼날의 길을 암기하며 수련을 거듭했다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L1_1.m_bTalkCenterFadeIn = true
L2_1 = "それ以来、しばらく洞窟に刻まれた刃先の流れを暗記しながら修練を重ねた。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "After that day, I trained inside that cave, memorizing the blade's path engraved on the wall."
L1_1.m_Talk_ENG = L2_1
L2_1 = "在那之後，我記下刻在洞穴裡的每一條劍痕，不斷反覆練習。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "หลังจากวันนั้น ข้าก็ฝึกในถ้ำนั่น คอยจดจำวิถีดาบที่สลักเลาลงบนผนัง"
L1_1.m_Talk_THA = L2_1
L2_1 = "Sau ngày hôm đó, mình vẫn luôn luyện tập trong hang động ấy, ghi nhớ mọi đường kiếm được khắc trên vách đá."
L1_1.m_Talk_VTN = L2_1
L2_1 = "那之后，我记下洞窟中的每一条剑痕，不断反复练习。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Von diesem Tag an trainierte ich in dieser Höhle und prägte mir den Weg der Klinge ein, der in die Wand eingraviert war."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Depuis ce jour, je me suis entraînée sans relâche à l'intérieur de cette grotte en me repérant grâce aux taillades sur les murs."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NANAHARA2_ACT2_INTERLUDE1@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5100201
L2_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "하지만 결국 성공하지 못했다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L2_1.m_bTalkCenterFadeIn = true
L3_1 = "だが、結局成功しなかった。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "But in the end, I was not able to succeed."
L2_1.m_Talk_ENG = L3_1
L3_1 = "結果還是失敗收場。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "แต่สุดท้ายแล้วข้าก็ทำไม่สำเร็จ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Nhưng cuối cùng, mình vẫn không thể thành công."
L2_1.m_Talk_VTN = L3_1
L3_1 = "但是最终还是没能成功。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Aber am Ende gelang es mir trotzdem nicht."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Mais malgré tous mes efforts, je n'ai jamais réussi."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "NANAHARA2_ACT2_INTERLUDE1@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5100201
L3_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "흠집을 따라 검을 휘두르는 것은 가능했으나, 그 동세는 무척이나 부자연스러웠다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L3_1.m_bTalkCenterFadeIn = true
L4_1 = "傷跡をなぞって刀を振るうことは可能だったが、その動きはとても不自然だった。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I was able to replicate the swing along the path, but the momentum was unnatural."
L3_1.m_Talk_ENG = L4_1
L4_1 = "雖然可以模仿痕跡揮劍，姿勢卻非常不自然。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ข้าอาจเลียนแบบวิถีการกวัดแกว่งได้ แต่เรื่องน้ำหนักในการฟาดฟันนั้นกลับไม่ลงตัวเลย"
L3_1.m_Talk_THA = L4_1
L4_1 = "Mình có thể bắt chước mọi đường kiếm, nhưng lực thì không đủ."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我能照着刻痕挥剑，但挥剑的姿态却非常不自然。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ich konnte den Schwung zwar nachahmen, aber es war so unnatürlich."
L3_1.m_Talk_DEU = L4_1
L4_1 = "J'avais beau agiter ma lame en reproduisant les élans laissés par les marques, mes mouvements semblaient artificiels."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "NANAHARA2_ACT2_INTERLUDE1@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 5100201
L4_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "어쩌면 이것이 타고나지 못한 자의 한계일지도 모른다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L4_1.m_bTalkCenterFadeIn = true
L5_1 = "もしかするとこれが生まれつき才能のない者の限界なのかもしれない。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Perhaps this was the limit for the untalented."
L4_1.m_Talk_ENG = L5_1
L5_1 = "或許一個沒有天賦的人天生就是做不來。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "บางทีนี่อาจเป็นขีดจำกัดของผู้ไร้สามารถ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Có lẽ đây là giới hạn của những người không phải là thiên tài."
L4_1.m_Talk_VTN = L5_1
L5_1 = "或许这就是没有天赋之人的极限。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Vielleicht war dies die Grenze für die Untalentierten."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Sans doute étaient-ce mes limites."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "NANAHARA2_ACT2_INTERLUDE1@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5100201
L5_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "하지만 당주님을 또다시 지키지 못할 상황이 오게 된다면 나는……"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L5_1.m_bTalkCenterFadeIn = true
L6_1 = "でも、また当主を守れなくなる状況が来れば私は……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But if there ever is another time when I am not able to protect Lady Nanahara, I..."
L5_1.m_Talk_ENG = L6_1
L6_1 = "不過要是又發生無法保護堂主的情況，那我……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แต่หากไม่อาจปกป้องนางอีกครั้ง ข้า..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Nhưng nếu mình lại không thể bảo vệ chị ấy một lần nữa, mình..."
L5_1.m_Talk_VTN = L6_1
L6_1 = "但是，如果再遇到我无法保护家主的情况，那我……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Aber wenn jemals wieder der Moment kommt, in dem ich die Anführerin nicht beschützen kann, dann ..."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais si je devais de nouveau échouer à protéger Dame Nanahara, alors je..."
L5_1.m_Talk_FRA = L6_1
