L8_1.m_CharStrID = L9_1
L9_1 = "근심이 있어 보이는 한숨소리로군요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "悩みがありそうな溜息ですね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "That is one worrisome sigh."
L8_1.m_Talk_ENG = L9_1
L9_1 = "您看起來好像有心事。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เป็นเสียงถอนหายใจที่ฟังดูกังวลยิ่งนะคะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Đó là tiếng thở dài đáng lo đấy."
L8_1.m_Talk_VTN = L9_1
L9_1 = "您听起来好像有烦心的事。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Das ist aber ein besorgniserregender Seufzer."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Ça, c'est un soupir qui en dit long sur vos inquiétudes."
L8_1.m_Talk_FRA = L9_1
