L12_1 = "NANAHARA2_ACT2_INTERLUDE1@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 5100201
L11_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "UNIT_SURPRISE"
L11_1.m_Face = L12_1
L12_1 = "CHIFUYU_NANA_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "L"
L11_1.m_Pos = L12_1
L12_1 = "하야미 공? 여긴 어쩐 일로 오셨습니까?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "速水殿？　ここにはどうして？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Dame Sanae? What brings you here?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "速水？你來這裡做什麼？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "นายท่านฮายามิ? มาทำอะไรที่นี่หรือคะ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Lãnh Chúa Hayami? Sao cô lại tới đây?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "速水？您怎么会来这里？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Sanae? Was bringt Sie denn hierher?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Dame Sanae ? Qu'est-ce qui vous amène ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "NANAHARA2_ACT2_INTERLUDE1@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5100201
L12_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "UNIT_LAUGH"
L12_1.m_Face = L13_1
L13_1 = "SANAE_NANA_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "R"
L12_1.m_Pos = L13_1
L13_1 = "당주님의 분부로 명을 수행하고 돌아오는 길입니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "当主様に命ぜられた仕事を片付けて帰ってきたところです。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I am on my way back from carrying out an order from Lady Nanahara."
L12_1.m_Talk_ENG = L13_1
L13_1 = "我剛完成堂主的吩咐回來。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ข้าน้อยกำลังกลับจากการฝึกฝนตามคำสั่งของท่านหญิงนานะฮาระค่ะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi đang trên đường trở về sau khi tập luyện theo lệnh của Tiểu Thư Nanahara."
L12_1.m_Talk_VTN = L13_1
L13_1 = "奉家主之命，我刚执行完任务回来。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich habe einen Befehl der Anführerin aufgeführt und bin nun auf dem Rückweg."
L12_1.m_Talk_DEU = L13_1
L13_1 = "J'effectuais une mission pour Dame Nanahara, et je me suis dit que j'allais venir vous voir."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "NANAHARA2_ACT2_INTERLUDE1@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5100201
L13_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "SANAE_NANA_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "R"
L13_1.m_Pos = L14_1
L14_1 = "그리고, 나오님께서 이 검을 돌려주라고 하시더군요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それに、ナオ様がこの刀を返すようにと。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Also, Miss Nao told me to give this blade back to you."
L13_1.m_Talk_ENG = L14_1
L14_1 = "另外，奈緒大人請我把這把劍還給您。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "และท่านนาโอะก็ให้ข้าน้อยนำดาบนี่มาคืนให้ท่านด้วย"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ngoài ra, Cô Nao cũng đã bảo tôi mang trả thanh kiếm này cho cô."
L13_1.m_Talk_VTN = L14_1
L14_1 = "还有，奈绪大人说让我把这把剑还给您。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Außerdem hat mir Fräulein Nao gesagt, ich solle Ihnen dieses Schwert zurückgeben."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Oh, et madame Nao m'a dit de vous remettre cette épée."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
