L16_1 = "NANAHARA2_ACT2_INTERLUDE1@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5100201
L15_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "UNIT_SURPRISE"
L15_1.m_Face = L16_1
L16_1 = "CHIFUYU_NANA_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "L"
L15_1.m_Pos = L16_1
L15_1.m_Crash = 20
L16_1 = "감사합니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ありがとうございます。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Thank you."
L15_1.m_Talk_ENG = L16_1
L16_1 = "謝謝你。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ขอบคุณค่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cảm ơn."
L15_1.m_Talk_VTN = L16_1
L16_1 = "谢谢。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Vielen Dank."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Merci."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NANAHARA2_ACT2_INTERLUDE1@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 5100201
L16_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "UNIT_LAUGH"
L16_1.m_Face = L17_1
L17_1 = "CHIFUYU_NANA_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "L"
L16_1.m_Pos = L17_1
L17_1 = "날이 전보다 예리해졌음에도 무게는 여전히 같군요. 신기합니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "刃が前より鋭くなっているのに重さは変わらない。不思議です。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "It's strange. The edge is sharper than before, but it seems to weigh the same."
L16_1.m_Talk_ENG = L17_1
L17_1 = "雖然刀鋒比以前銳利，重量卻一點也沒變，真是神奇。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แปลกนะคะ ดาบดูจะคมกว่าเดิม แต่น้ำหนักเท่าเดิมเลย"
L16_1.m_Talk_THA = L17_1
L17_1 = "Thật kỳ lạ. Cạnh thì sắc hơn trước, nhưng trọng lượng thì như cũ."
L16_1.m_Talk_VTN = L17_1
L17_1 = "剑刃比之前更锋利了，但重量还是一样。真神奇。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Beeindruckend. Die Klinge ist schärfer als zuvor, scheint aber genauso schwer zu sein."
L16_1.m_Talk_DEU = L17_1
L17_1 = "C'est étrange. La lame est plus affûtée qu'avant et pourtant, le poids est le même."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "NANAHARA2_ACT2_INTERLUDE1@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5100201
L17_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "UNIT_LAUGH"
L17_1.m_Face = L18_1
L18_1 = "SANAE_NANA_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "R"
L17_1.m_Pos = L18_1
L18_1 = "나오님은 저희 하야미 집안의 도구도 여럿 만들어주신 무기의 장인이시니까요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ナオ様は速水家の道具も多く作ってこられた武器職人ですから。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "That is because Miss Nao is a master weaponsmith who has been forging various tools for the Hayami family."
L17_1.m_Talk_ENG = L18_1
L18_1 = "奈緒大人也替我們速水家族製造過一些武器，她可是武器達人呢。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "นั่นเพราะท่านนาโอะเป็นช่างทำอาวุธยอดฝีมือที่ทำเครื่องมือให้ตระกูลฮายามิมามากมายค่ะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Đó là vì Cô Nao là thợ rèn bậc thầy. Cô ấy đã rèn nhiều công cụ cho gia tộc Hayami rồi."
L17_1.m_Talk_VTN = L18_1
L18_1 = "奈绪大人是出色的武器匠人，我们速水家族的很多武器也都是她锻造的。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Das liegt daran, dass Fräulein Nao eine Waffenschmiedin ist, die verschiedene Werkzeuge für die Familie Hayami hergestellt hat."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Madame Nao est une forgeronne d'exception, c'est elle qui a forgé toutes les armes de la famille Hayami."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "NANAHARA2_ACT2_INTERLUDE1@218#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 218
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 5100201
L18_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "UNIT_DESPAIR"
L18_1.m_Face = L19_1
L19_1 = "CHIFUYU_NANA_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "L"
L18_1.m_Pos = L19_1
L19_1 = "……한 사람의 도움이 더 필요한 때에 이런 꼴을 보여 면목이 없군요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "……一人でも多くの手が必要な時にこんな姿をお見せして面目ありません。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "...I'm sorry to be like this when you need every help you can get."
L18_1.m_Talk_ENG = L19_1
L19_1 = "……現在正需要人手的時候，我卻是這副德性，真是沒臉見人。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ขออภัยที่ข้าเป็นเช่นนี้ในยามที่ท่านต้องใช้ความช่วยเหลือทุกอย่างที่หาได้นะคะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Tôi xin lỗi vì cứ thế này mỗi khi cô cần mọi sự giúp đỡ cần thiết."
L18_1.m_Talk_VTN = L19_1
L19_1 = "……在如此需要人力的时候，让您看到我的这副模样，我很惭愧。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "... Es tut mir leid, dass ich nicht mehr tun kann, obwohl gerade jedes Mitglied der Familienallianz gebraucht wird."
L18_1.m_Talk_DEU = L19_1
L19_1 = "... Je suis désolée de vous décevoir encore une fois, quand vous avez besoin de moi."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "NANAHARA2_ACT2_INTERLUDE1@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 5100201
L19_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "SANAE_NANA_NULL_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "R"
L19_1.m_Pos = L20_1
L20_1 = "그런 말씀 마십시오. 치후유님의 노력을 이해하지 못하는 연합원은 없습니다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "何をおっしゃいますか。千冬様の努力を理解できない連合員はいません。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Don't be. Every member understands the effort you put into, Miss Chifuyu."
L19_1.m_Talk_ENG = L20_1
L20_1 = "別這麼說，大家都能理解你的努力的。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "อย่าได้กล่าวเช่นนั้นเลยค่ะ สมาชิกทุกคนเข้าใจในความทุ่มเทของท่านนะคะ ท่านชิฟุยุ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Đừng như vậy. Mỗi thành viên đều hiểu cô đã nỗ lực đến mức nào, Cô Chifuyu à."
L19_1.m_Talk_VTN = L20_1
L20_1 = "请不要说这种话。所有联盟成员都理解千冬的努力。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Sagen Sie so etwas nicht. Jedes Mitglied versteht, wie sehr Sie sich anstrengen, Fräulein Chifuyu."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Ne dites pas ça. Tout le monde sait à quel point vous vous démenez, Chifuyu."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "NANAHARA2_ACT2_INTERLUDE1@220#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5100201
L20_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "CHIFUYU_NANA_NULL_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "L"
L20_1.m_Pos = L21_1
L21_1 = "그간의 수련이 무색하게도, 저는 오른팔을 움직이지 못하게 됐습니다."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "これまでの修練もむなしく右腕が動かなくなりました。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "But even with all the training, I cannot move my right arm now."
L20_1.m_Talk_ENG = L21_1
L21_1 = "這陣子的練習也派不上用場，我的右手臂完全無法動彈。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "แต่ถึงจะฝึกมาทั้งหมดแล้ว ข้าก็ยังใช้แขนขวาไม่ได้อยู่ดี"
L20_1.m_Talk_THA = L21_1
L21_1 = "Nhưng dù đã tập luyện bao lâu, tôi vẫn không thể cử động cánh tay phải của mình."
L20_1.m_Talk_VTN = L21_1
L21_1 = "真是愧对这段时间的修炼，我的右臂不能动了。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Aber trotz des Trainings kann ich meinen rechten Arm noch immer nicht bewegen."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Malgré mon entraînement intensif, je suis toujours incapable de bouger mon bras droit."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "NANAHARA2_ACT2_INTERLUDE1@221#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 221
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5100201
L21_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "CHIFUYU_NANA_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "L"
L21_1.m_Pos = L22_1
L22_1 = "회복할 수 있는 상처인지도 불분명하다고 합니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "回復できる傷なのかも定かではありません。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "They cannot tell if this wound will even ever heal."
L21_1.m_Talk_ENG = L22_1
L22_1 = "而且是否能夠痊癒也是個未知數，"
L21_1.m_Talk_TWN = L22_1
L22_1 = "พวกเขาบอกไม่ได้ว่าแผลนี้จะมีวันหายหรือไม่ด้วยซ้ำ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Chẳng biết bao giờ vết thương này mới lành lại."
L21_1.m_Talk_VTN = L22_1
L22_1 = "伤口能否恢复也不确定。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich weiß nicht, ob diese Wunde jemals heilen wird."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Les médecins sont incapables de me dire si j'en retrouverai jamais l'usage."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NANAHARA2_ACT2_INTERLUDE1@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5100201
L22_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "CHIFUYU_NANA_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "L"
L22_1.m_Pos = L23_1
L23_1 = "이대로는 지금의 저는 당주님에게 짐이 될 뿐입니다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "このままでは、私は当主の足手まといになるだけです。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "At this rate, all I will be is a burden to Lady Nanahara."
L22_1.m_Talk_ENG = L23_1
L23_1 = "這樣下去，現在的我只會成為堂主的負擔。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ซึ่งถ้าเป็นเช่นนี้ ข้าคงเป็นได้เพียงภาระของท่านหญิงนานะฮาระ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Cứ thế này tôi sẽ trở thành gánh nặng với Tiểu Thư Nanahara mất."
L22_1.m_Talk_VTN = L23_1
L23_1 = "照这样下去，如今的我只会成为家主的累赘。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "In diesem Zustand werde ich der Anführerin nur zur Last fallen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Dans cet état, je ne suis qu'un fardeau pour Dame Nanahara."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NANAHARA2_ACT2_INTERLUDE1@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 5100201
L23_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "UNIT_IDLE"
L23_1.m_Face = L24_1
L24_1 = "SANAE_NANA_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "R"
L23_1.m_Pos = L24_1
L24_1 = "치후유님은 나나하라류의 모든 것을 익히셨습니다. 더는 수련을 통해 성장할 수 없을 정도로 말이지요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "千冬様は七原流のすべてを身につけました。もう修練を通じては成長できないほどに。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "You have learned everything there is to know about the Nanahara style, Miss Chifuyu. Enough so that more training will not improve your skills."
L23_1.m_Talk_ENG = L24_1
L24_1 = "您已經熟悉七原流的劍法，再練下去也無法進步的。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ท่านได้เรียนรู้ทุกสิ่งที่จำเป็นต้องรู้เกี่ยวกับวิชาต่อสู้สายนานะฮาระแล้วนะคะท่านชิฟุยุ มากเสียจนให้ฝึกหนักไปกว่านี้ก็พัฒนาฝีมือไม่ได้แล้ว"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cô đã học mọi thứ cần biết về Trường Phái Nanahara, cô Chifuyu. Đủ đến mức tập luyện nữa cũng không có tác dụng nâng cao kỹ năng của cô."
L23_1.m_Talk_VTN = L24_1
L24_1 = "您已经学会了七原流的一切，再继续修炼下去也无法进步的。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Sie haben alles gelernt, was es über den Nanahara-Stil zu wissen gibt, Fräulein Chifuyu. Mehr Training würde Ihre Fähigkeiten auch nicht verbessern."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Vous avez appris tout ce qu'il y a à savoir sur le style de l'école Nanahara, Chifuyu. Continuer ainsi ne vous fera pas progresser davantage."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "NANAHARA2_ACT2_INTERLUDE1@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 5100201
L24_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "UNIT_DESPAIR"
L24_1.m_Face = L25_1
L25_1 = "CHIFUYU_NANA_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "L"
L24_1.m_Pos = L25_1
L25_1 = "알고 있습니다. 이런 상태로 수련장소를 찾는다고 해서 달리 방도가 없다는 건……"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "わかっているんです。このような状態で修練場を訪れても解決の糸口は見つからないと……"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I think so too. I know that training in this state will not change anything..."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我知道，在這種狀態下來到修練的地方也無計可施……"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ข้าเองก็คิดเช่นนั้นค่ะ ข้ารู้ว่าการฝึกในสภาพนี้ไม่ได้ทำให้อะไรดีขึ้นเลย..."
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi cũng nghĩ vậy. Tôi biết rằng tập luyện ở trạng thái này sẽ chẳng thay đổi được gì..."
L24_1.m_Talk_VTN = L25_1
L25_1 = "我知道。在这种情况下，即便继续修炼也无计可施……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich weiß. In diesem Zustand zu trainieren, bringt rein gar nichts ..."
L24_1.m_Talk_DEU = L25_1
L25_1 = "J'en suis consciente. Je sais bien que m'entraîner ne me mènera nulle part dans mon état, mais..."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "NANAHARA2_ACT2_INTERLUDE1@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5100201
L25_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "CHIFUYU_NANA_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "L"
L25_1.m_Pos = L26_1
L26_1 = "그럼에도 미련이 남아, 이곳에 발길이 닿았을 뿐입니다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "それでも未練がましくここに来てしまいました。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "But there is still this lingering feeling, which is why I came here."
L25_1.m_Talk_ENG = L26_1
L26_1 = "只是我還是放不下，才會來這裡。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "แต่ความรู้สึกนั้นมันก็ยังวนเวียน ข้าจึงได้มาที่นี่ค่ะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Nhưng cảm giác này vẫn cứ sôi sục trong tôi, đó là lý do tại sao tôi tới đây."
L25_1.m_Talk_VTN = L26_1
L26_1 = "但我还是放不下，不知不觉就走到了这里。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Aber es bleibt immer noch dieses Gefühl, weshalb ich hierher gekommen bin."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Mais cet endroit... j'y suis attachée."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
