L29_1 = "NANAHARA2_ACT2_INTERLUDE1@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 5100201
L28_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "UNIT_IDLE"
L28_1.m_Face = L29_1
L29_1 = "SANAE_NANA_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "치후유님은 장님동굴에 새겨진 검식들을 모두 암기하고 계시는지요?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "千冬様は晦冥の洞窟に刻まれている傷をすべて暗記なさっていますか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I have heard you memorized every marking in the Cave of Blinds, correct?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "您有把刻在盲穴中的招式都背下來對吧？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เห็นว่าท่านจำทุกร่องรอยในถ้ำแห่งความมืดบอดได้แล้วใช่หรือไม่คะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tôi nghe nói cô đã ghi nhớ mọi dấu vết trong Hang Mù, phải không?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "您已经记住盲眼洞窟中刻着的全部剑招了吧？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ich habe gehört, dass Sie sich jede Eingravierung in der Höhle eingeprägt haben, nicht wahr?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "J'ai entendu que vous aviez mémorisé l'emplacement de chaque taillade sur les murs. Est-ce vrai ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "NANAHARA2_ACT2_INTERLUDE1@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5100201
L29_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "UNIT_DESPAIR"
L29_1.m_Face = L30_1
L30_1 = "CHIFUYU_NANA_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "기억은 하고 있으나, 그것을 검술로 구현할 역량은 되지 못합니다."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "覚えてはいますが、それを剣術として具現化する力量はありません。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I have, but I lack the ability to incorporate it into my combat techniques."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我是還記得，但那不足以成為一套劍法。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ค่ะ แต่ก็ยังไม่อาจผสานเข้าไปในวิชาต่อสู้ของข้าได้อยู่ดี"
L29_1.m_Talk_THA = L30_1
L30_1 = "Đúng thế, nhưng tôi không thể kết hợp chúng thành kỹ năng chiến đấu của mình."
L29_1.m_Talk_VTN = L30_1
L30_1 = "我虽然记得剑招，但没有能力让剑招变成剑法。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Das stimmt, aber mir fehlt die Fähigkeit, es in meine Schwertkunst zu integrieren."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Oui. Mais je n'arrive toujours pas à reproduire les mouvements parfaitement."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "NANAHARA2_ACT2_INTERLUDE1@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5100201
L30_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "CHIFUYU_NANA_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "더군다나 지금은 팔을 다쳤으니까요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "それに今は腕を怪我してもいます。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Even more so, because of the state of my arm."
L30_1.m_Talk_ENG = L31_1
L31_1 = "更何況我現在手臂還受傷。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ยิ่งกว่านั้นคือด้วยสภาพแขนข้า"
L30_1.m_Talk_THA = L31_1
L31_1 = "Còn tệ hơn nữa, vì trạng thái cánh tay của tôi hiện tại."
L30_1.m_Talk_VTN = L31_1
L31_1 = "更何况现在我的胳膊还受伤了。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Darüber hinaus ist mein Arm verletzt."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Et encore moins avec le bras dans cet état."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NANAHARA2_ACT2_INTERLUDE1@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5100201
L31_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "SANAE_NANA_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "팔 하나를 쓰지 못해도 방법은 있습니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "腕一本使えなくとも方法はあります。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "There are still ways to use it with one arm."
L31_1.m_Talk_ENG = L32_1
L32_1 = "就算有一隻手臂無法使，還是有辦法的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ยังมีอีกหลายวิธีที่จะใช้ด้วยแขนเดียวนะคะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Vẫn có nhiều cách để ứng dụng bằng một tay."
L31_1.m_Talk_VTN = L32_1
L32_1 = "就算一只胳膊不能用也有办法。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Auch wenn Sie einen Arm nicht nutzen können, so gibt es dennoch einen Weg."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Même en étant estropiée, il y a tout de même une solution."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "NANAHARA2_ACT2_INTERLUDE1@232#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 232
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5100201
L32_1.m_CutScenStrID = "NANAHARA2_ACT2_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "SANAE_NANA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "가르침은 아니지만, 원하신다면 치후유님이 더 강한 적에게 맞설 수 있도록 도움을 드리지요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "教えではありませんが、よろしければ千冬様がより強い敵に立ち向かえるようお手伝いいたしましょう。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Miss Chifuyu, I'm not trying to teach you anything. However, I can help you so that you can take on more formidable opponents if you wish."
L32_1.m_Talk_ENG = L33_1
L33_1 = "不敢說是教，但您若願意，我可以幫助您能夠面對更強大的敵人。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ท่านชิฟุยุ ข้าน้อยมิได้กำลังพยายามจะสอนอะไรหรอกนะคะ แต่หากท่านต้องการข้าน้อยก็ช่วยได้ ท่านจะได้สามารถกำจัดศัตรูที่น่าเกรงขามกว่านี้ได้"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cô Chifuyu, tôi không cố dạy cô điều gì cả. Tuy nhiên, tôi có thể giúp cô có khả năng đối đầu với nhiều kẻ thù đáng gờm hơn nếu cô muốn."
L32_1.m_Talk_VTN = L33_1
L33_1 = "虽然算不上是传授技巧，但如果您愿意，我可以帮助您对抗更强大的敌人。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Fräulein Chifuyu, ich versuche nicht, Ihnen etwas beizubringen. Ich kann Ihnen jedoch helfen, damit Sie es mit einem stärkeren Gegnern aufnehmen können."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Si vous le souhaitez, je peux vous aider à vous préparer pour affronter des ennemis plus puissants, Chifuyu."
L32_1.m_Talk_FRA = L33_1
